fn register_spring_codec_intrinsics(registry: &mut NativeMethodRegistry) {
    registry.register(
        "org/springframework/core/codec/CharSequenceEncoder",
        "calculateCapacity",
        "(Ljava/lang/CharSequence;Ljava/nio/charset/Charset;)I",
        native_spring_char_sequence_encoder_calculate_capacity,
    );

    registry.register(
        "org/springframework/core/annotation/PackagesAnnotationFilter",
        "matches",
        "(Ljava/lang/String;)Z",
        native_spring_packages_annotation_filter_matches,
    );
    registry.register(
        "org/springframework/core/annotation/AnnotationFilter",
        "matches",
        "(Ljava/lang/Class;)Z",
        native_spring_annotation_filter_matches_class,
    );
    registry.register(
        "org/springframework/core/annotation/AnnotationsScanner",
        "hasPlainJavaAnnotationsOnly",
        "(Ljava/lang/Class;)Z",
        native_spring_has_plain_java_annotations_only_class,
    );
    registry.register(
        "org/springframework/core/annotation/AnnotationsScanner",
        "hasPlainJavaAnnotationsOnly",
        "(Ljava/lang/Object;)Z",
        native_spring_has_plain_java_annotations_only_object,
    );
    registry.register(
        "org/junit/platform/commons/util/AnnotationUtils",
        "isInJavaLangAnnotationPackage",
        "(Ljava/lang/Class;)Z",
        native_junit_is_in_java_lang_annotation_package,
    );
    registry.register(
        "org/springframework/test/context/junit/jupiter/SpringExtension",
        "resolveParameter",
        "(Lorg/junit/jupiter/api/extension/ParameterContext;Lorg/junit/jupiter/api/extension/ExtensionContext;)Ljava/lang/Object;",
        native_spring_extension_resolve_parameter,
    );
}

fn native_spring_char_sequence_encoder_calculate_capacity(
    ctx: &mut dyn NativeContext,
    args: &[Value],
) -> MethodCallResult {
    let seq = match args.get(1) {
        Some(Value::Object(Some(obj))) => *obj,
        _ => return Ok(Some(Value::Int(0))),
    };

    let len = if let Some(text) = ctx.read_string(seq) {
        text.encode_utf16().count() as i64
    } else {
        match ctx.invoke_virtual(seq, "length", "()I", &[])? {
            Some(Value::Int(n)) if n > 0 => n as i64,
            _ => 0,
        }
    };

    let capacity = len.saturating_mul(8).min(i32::MAX as i64) as i32;
    Ok(Some(Value::Int(capacity)))
}

fn spring_java_class_name(ctx: &mut dyn NativeContext, class_obj: ObjectRef) -> Option<String> {
    match native_class_get_name(ctx, &[Value::Object(Some(class_obj))]) {
        Ok(Some(Value::Object(Some(name)))) => ctx.read_string(name),
        _ => None,
    }
}

fn spring_packages_filter_matches_text(
    ctx: &mut dyn NativeContext,
    filter: ObjectRef,
    annotation_type: &str,
) -> bool {
    let prefixes = match ctx.get_field_by_name(filter, "prefixes") {
        Value::Object(Some(prefixes)) => prefixes,
        _ => return false,
    };
    for i in 0..ctx.array_length(prefixes) {
        if let Value::Object(Some(prefix)) = ctx.get_array_element(prefixes, i) {
            if let Some(prefix) = ctx.read_string(prefix) {
                if annotation_type.starts_with(&prefix) {
                    return true;
                }
            }
        }
    }
    false
}

fn native_spring_packages_annotation_filter_matches(
    ctx: &mut dyn NativeContext,
    args: &[Value],
) -> MethodCallResult {
    let this = obj_arg(args, 0)?;
    let annotation_type = match args.get(1) {
        Some(Value::Object(Some(s))) => ctx.read_string(*s).unwrap_or_default(),
        _ => return Ok(Some(Value::Int(0))),
    };
    Ok(Some(Value::Int(
        spring_packages_filter_matches_text(ctx, this, &annotation_type) as i32,
    )))
}

fn native_spring_annotation_filter_matches_class(
    ctx: &mut dyn NativeContext,
    args: &[Value],
) -> MethodCallResult {
    let this = obj_arg(args, 0)?;
    let class_obj = obj_arg(args, 1)?;
    let Some(type_name) = spring_java_class_name(ctx, class_obj) else {
        return Ok(Some(Value::Int(0)));
    };

    if ctx
        .class_name_of_id(ctx.class_id_of_object(this))
        .as_deref()
        == Some("org/springframework/core/annotation/PackagesAnnotationFilter")
    {
        return Ok(Some(Value::Int(
            spring_packages_filter_matches_text(ctx, this, &type_name) as i32,
        )));
    }

    let type_name_obj = ctx.create_string(&type_name);
    ctx.invoke_virtual(
        this,
        "matches",
        "(Ljava/lang/String;)Z",
        &[Value::Object(Some(type_name_obj))],
    )
}

fn native_junit_is_in_java_lang_annotation_package(
    ctx: &mut dyn NativeContext,
    args: &[Value],
) -> MethodCallResult {
    let class_obj = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Int(0))),
    };
    let matched = spring_java_class_name(ctx, class_obj)
        .map(|name| name.starts_with("java.lang.annotation"))
        .unwrap_or(false);
    Ok(Some(Value::Int(matched as i32)))
}

fn spring_has_plain_java_annotations_only_name(name: &str) -> bool {
    name.starts_with("java.") || name == "org.springframework.core.Ordered"
}

fn native_spring_has_plain_java_annotations_only_class(
    ctx: &mut dyn NativeContext,
    args: &[Value],
) -> MethodCallResult {
    let class_obj = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Int(0))),
    };
    let matched = spring_java_class_name(ctx, class_obj)
        .map(|name| spring_has_plain_java_annotations_only_name(&name))
        .unwrap_or(false);
    Ok(Some(Value::Int(matched as i32)))
}

fn native_spring_has_plain_java_annotations_only_object(
    ctx: &mut dyn NativeContext,
    args: &[Value],
) -> MethodCallResult {
    let annotated = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Int(0))),
    };
    let class_name = ctx.class_name_of_id(ctx.class_id_of_object(annotated));
    if class_name.as_deref() == Some("java/lang/Class") {
        return native_spring_has_plain_java_annotations_only_class(ctx, args);
    }
    if matches!(
        class_name.as_deref(),
        Some("java/lang/reflect/Method")
            | Some("java/lang/reflect/Constructor")
            | Some("java/lang/reflect/Field")
    ) {
        if let Ok(Some(Value::Object(Some(declaring)))) =
            ctx.invoke_virtual(annotated, "getDeclaringClass", "()Ljava/lang/Class;", &[])
        {
            return native_spring_has_plain_java_annotations_only_class(
                ctx,
                &[Value::Object(Some(declaring))],
            );
        }
    }
    Ok(Some(Value::Int(0)))
}

fn spring_extension_get_application_context(
    ctx: &mut dyn NativeContext,
    extension_context: ObjectRef,
) -> MethodCallResult {
    ctx.invoke_special(
        "org/springframework/test/context/junit/jupiter/SpringExtension",
        "getApplicationContext",
        "(Lorg/junit/jupiter/api/extension/ExtensionContext;)Lorg/springframework/context/ApplicationContext;",
        &[Value::Object(Some(extension_context))],
    )
}

fn native_spring_extension_resolve_parameter(
    ctx: &mut dyn NativeContext,
    args: &[Value],
) -> MethodCallResult {
    let parameter_context = obj_arg(args, 1)?;
    let mut extension_context = obj_arg(args, 2)?;

    let parameter = match ctx.invoke_virtual(
        parameter_context,
        "getParameter",
        "()Ljava/lang/reflect/Parameter;",
        &[],
    )? {
        Some(Value::Object(Some(parameter))) => parameter,
        _ => return Ok(Some(Value::Object(None))),
    };
    let index = ctx
        .invoke_virtual(parameter_context, "getIndex", "()I", &[])?
        .and_then(|v| v.as_int())
        .unwrap_or(0);
    let executable = match ctx.invoke_virtual(
        parameter_context,
        "getDeclaringExecutable",
        "()Ljava/lang/reflect/Executable;",
        &[],
    )? {
        Some(Value::Object(Some(executable))) => executable,
        _ => return Ok(Some(Value::Object(None))),
    };
    let mut test_class = match ctx.invoke_virtual(
        extension_context,
        "getRequiredTestClass",
        "()Ljava/lang/Class;",
        &[],
    )? {
        Some(Value::Object(Some(test_class))) => test_class,
        _ => return Ok(Some(Value::Object(None))),
    };

    if ctx
        .class_name_of_id(ctx.class_id_of_object(executable))
        .as_deref()
        == Some("java/lang/reflect/Constructor")
    {
        if let Ok(Some(Value::Object(Some(declaring)))) =
            ctx.invoke_virtual(executable, "getDeclaringClass", "()Ljava/lang/Class;", &[])
        {
            test_class = declaring;
            if let Ok(Some(Value::Object(Some(scoped)))) = ctx.invoke_special(
                "org/springframework/test/context/junit/jupiter/SpringExtension",
                "findProperlyScopedExtensionContext",
                "(Ljava/lang/Class;Lorg/junit/jupiter/api/extension/ExtensionContext;)Lorg/junit/jupiter/api/extension/ExtensionContext;",
                &[
                    Value::Object(Some(test_class)),
                    Value::Object(Some(extension_context)),
                ],
            ) {
                extension_context = scoped;
            }
        }
    }

    // Spring Framework 7.0.7 delegates every parameter shape directly to
    // ParameterResolutionDelegate. Keep this native mirror deliberately
    // narrow: the former ApplicationContext / BeanOverride branches drifted
    // from Spring and linked a removed SpringExtension.isBeanOverride method.
    let application_context = spring_extension_get_application_context(ctx, extension_context)?;
    let bean_factory_result = match application_context {
        Some(Value::Object(Some(application_context))) => ctx.invoke_virtual(
            application_context,
            "getAutowireCapableBeanFactory",
            "()Lorg/springframework/beans/factory/config/AutowireCapableBeanFactory;",
            &[],
        )?,
        other => return Ok(other),
    };
    let bean_factory = match bean_factory_result {
        Some(Value::Object(Some(bean_factory))) => bean_factory,
        _ => return Ok(Some(Value::Object(None))),
    };
    ctx.invoke_special(
        "org/springframework/beans/factory/annotation/ParameterResolutionDelegate",
        "resolveDependency",
        "(Ljava/lang/reflect/Parameter;ILjava/lang/Class;Lorg/springframework/beans/factory/config/AutowireCapableBeanFactory;)Ljava/lang/Object;",
        &[
            Value::Object(Some(parameter)),
            Value::Int(index),
            Value::Object(Some(test_class)),
            Value::Object(Some(bean_factory)),
        ],
    )
}

/// Native `Duration.parse(CharSequence)` for real-JDK mode.
///
/// JDK 25's `Duration.parse` (Duration.java:395) drives a compiled regex
/// then calls `Matcher.start(int)` on optional groups; CratonVM's
/// synthetic Matcher throws AIOOBE on unmatched groups. Override the
/// static factory so common ISO-8601 inputs (Quarkus emits `P3D` /
/// `PT...` values from config defaults) parse without touching the
/// regex engine.
///
/// Supported grammar: `[+-]P[nD][T[nH][nM][n[.n]S]]`. Construction
/// is delegated to `Duration.ofSeconds(long, long)` so the resulting
/// object has the real-JDK field layout.
fn essential_dur_parse(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    fn parse_unsigned(b: &[u8]) -> Option<(u64, usize)> {
        let mut i = 0usize;
        let mut sign_present = false;
        if i < b.len() && (b[i] == b'+' || b[i] == b'-') {
            sign_present = true;
            i += 1;
        }
        let start = i;
        while i < b.len() && b[i].is_ascii_digit() {
            i += 1;
        }
        if i == start {
            return None;
        }
        let n: u64 = std::str::from_utf8(&b[start..i]).ok()?.parse().ok()?;
        let _ = sign_present;
        Some((n, i))
    }
    fn parse_signed(b: &[u8]) -> Option<(u64, i128, usize)> {
        let mut i = 0usize;
        let mut sign: i128 = 1;
        if i < b.len() && (b[i] == b'+' || b[i] == b'-') {
            if b[i] == b'-' {
                sign = -1;
            }
            i += 1;
        }
        let (n, consumed) = parse_unsigned(&b[i..])?;
        if consumed == 0 {
            return None;
        }
        // parse_unsigned consumed `consumed` bytes from b[i..]; but
        // parse_unsigned itself may have stripped its own sign — avoid
        // double-stripping by reading raw digits only here.
        let start = i;
        let mut j = i;
        while j < b.len() && b[j].is_ascii_digit() {
            j += 1;
        }
        if j == start {
            return None;
        }
        let n: u64 = std::str::from_utf8(&b[start..j]).ok()?.parse().ok()?;
        Some((n, sign, j))
    }
    // Pure ISO-8601 duration parser: `[+-]P[nD][T[nH][nM][n[.n]S]]`. Returns
    // `(seconds, nanos)`, or `None` when the text is not a valid ISO-8601
    // duration. On `None` the caller throws a real
    // `java.time.format.DateTimeParseException` — the same type
    // `java.time.Duration.parse` raises — because Spring's
    // `DurationFormatterUtils.parseIso8601` propagates the failure and callers
    // (DurationFormatterUtilsTests.parseIsoThrows) assert on that exact cause
    // type; an `IllegalArgumentException` here is observably wrong.
    fn parse_iso(trimmed: &str) -> Option<(i64, i64)> {
        let bytes = trimmed.as_bytes();
        if bytes.is_empty() {
            return None;
        }
        let mut i = 0usize;
        let mut negative = false;
        if bytes[i] == b'+' {
            i += 1;
        } else if bytes[i] == b'-' {
            negative = true;
            i += 1;
        }
        if i >= bytes.len() || (bytes[i] != b'P' && bytes[i] != b'p') {
            return None;
        }
        i += 1;
        let mut total_seconds: i128 = 0;
        let mut total_nanos: i32 = 0;
        let mut saw_any = false;
        // Days segment
        if i < bytes.len() && bytes[i] != b'T' && bytes[i] != b't' {
            let (n, sign, consumed) = parse_signed(&bytes[i..])?;
            i += consumed;
            if i >= bytes.len() || (bytes[i] != b'D' && bytes[i] != b'd') {
                return None;
            }
            i += 1;
            total_seconds = total_seconds.saturating_add(sign * n as i128 * 86_400);
            saw_any = true;
        }
        // Time segment
        if i < bytes.len() {
            if bytes[i] != b'T' && bytes[i] != b't' {
                return None;
            }
            i += 1;
            let mut last_pos = 0;
            let mut t_saw = false;
            while i < bytes.len() {
                let (n, sign, consumed) = parse_signed(&bytes[i..])?;
                i += consumed;
                // Fractional seconds (only valid before S, but parse leniently)
                let mut frac_nanos: i64 = 0;
                if i < bytes.len() && (bytes[i] == b'.' || bytes[i] == b',') {
                    i += 1;
                    let start = i;
                    while i < bytes.len() && bytes[i].is_ascii_digit() {
                        i += 1;
                    }
                    if start == i {
                        return None;
                    }
                    let take = (i - start).min(9);
                    let digits = &trimmed[start..start + take];
                    let mut nanos: i64 = digits.parse::<i64>().unwrap_or(0);
                    for _ in digits.len()..9 {
                        nanos *= 10;
                    }
                    frac_nanos = nanos;
                }
                if i >= bytes.len() {
                    return None;
                }
                let unit = bytes[i];
                i += 1;
                let pos = match unit {
                    b'H' | b'h' => 1,
                    b'M' | b'm' => 2,
                    b'S' | b's' => 3,
                    _ => return None,
                };
                if pos <= last_pos {
                    return None;
                }
                last_pos = pos;
                t_saw = true;
                saw_any = true;
                match pos {
                    1 => total_seconds = total_seconds.saturating_add(sign * n as i128 * 3600),
                    2 => total_seconds = total_seconds.saturating_add(sign * n as i128 * 60),
                    3 => {
                        total_seconds = total_seconds.saturating_add(sign * n as i128);
                        let mut combined = total_nanos as i64 + sign as i64 * frac_nanos;
                        while combined < 0 {
                            combined += 1_000_000_000;
                            total_seconds -= 1;
                        }
                        while combined >= 1_000_000_000 {
                            combined -= 1_000_000_000;
                            total_seconds += 1;
                        }
                        total_nanos = combined as i32;
                    }
                    _ => {}
                }
            }
            if !t_saw {
                return None;
            }
        }
        if !saw_any {
            return None;
        }
        if negative {
            let total = -(total_seconds * 1_000_000_000 + total_nanos as i128);
            total_seconds = total.div_euclid(1_000_000_000);
            total_nanos = total.rem_euclid(1_000_000_000) as i32;
        }
        let secs = total_seconds.clamp(i64::MIN as i128, i64::MAX as i128) as i64;
        Some((secs, total_nanos as i64))
    }

    let s_obj = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => {
            return Err(
                cratonvm_types::error::RuntimeError::IllegalArgumentException {
                    message: "Text cannot be null".to_string(),
                }
                .into(),
            )
        }
    };
    // Distinguish a genuine read failure (`None`) from an empty string
    // (`Some("")`). Previously this used `.unwrap_or_default()`, which
    // silently coerced an unreadable CharSequence into `""` and then
    // produced a misleading "Text cannot be parsed to a Duration: "
    // error — masking the real problem (the argument's String layout
    // could not be decoded). Surface that as an explicit error instead.
    let text = match ctx.read_string(s_obj) {
        Some(t) => t,
        None => {
            return Err(
                cratonvm_types::error::RuntimeError::IllegalArgumentException {
                    message: "Duration.parse: text argument could not be read as a CharSequence"
                        .to_string(),
                }
                .into(),
            )
        }
    };
    let trimmed = text.trim().to_string();
    let (secs, nanos) = match parse_iso(&trimmed) {
        Some(v) => v,
        None => return Err(throw_duration_parse_exc(ctx, &trimmed)),
    };
    // Delegate to JDK's `Duration.ofSeconds(long,long)` so the returned
    // object has the proper internal layout.
    match ctx.invoke(
        "java/time/Duration",
        "ofSeconds",
        "(JJ)Ljava/time/Duration;",
        &[Value::Long(secs), Value::Long(nanos)],
    ) {
        Ok(Some(v)) => Ok(Some(v)),
        Ok(None) => Err(throw_duration_parse_exc(ctx, &trimmed)),
        Err(e) => Err(e),
    }
}

/// Build the `java.time.format.DateTimeParseException` that
/// `java.time.Duration.parse` raises for malformed ISO-8601 text: message
/// "Text cannot be parsed to a Duration", the offending text as `parsedData`,
/// and `errorIndex` 0. Returned as an `ExceptionThrown` so callers that inspect
/// the cause type (Spring `DurationFormatterUtils`) observe the real JDK type.
/// Falls back to `IllegalArgumentException` only if the exception object cannot
/// be constructed.
fn throw_duration_parse_exc(ctx: &mut dyn NativeContext, text: &str) -> MethodCallFailed {
    let msg = ctx.create_string("Text cannot be parsed to a Duration");
    let parsed = ctx.create_string(text);
    match ctx.new_object_initialized(
        "java/time/format/DateTimeParseException",
        "(Ljava/lang/String;Ljava/lang/CharSequence;I)V",
        &[
            Value::Object(Some(msg)),
            Value::Object(Some(parsed)),
            Value::Int(0),
        ],
    ) {
        Ok(Some(Value::Object(Some(exc)))) => MethodCallFailed::ExceptionThrown(exc),
        _ => RuntimeError::IllegalArgumentException {
            message: format!("Text cannot be parsed to a Duration: {text}"),
        }
        .into(),
    }
}

/// Native override for `io.quarkus.runtime.configuration.LocaleConverter.convert(String)`.
///
/// The JDK-bytecode converter validates inputs via
/// `Locale.forLanguageTag(...).getLanguage().isEmpty()` and throws
/// `IllegalArgumentException("Unable to resolve locale: <input>")` on
/// failure. CratonVM's `Locale.forLanguageTag` doesn't populate the
/// language field in real-JDK mode, so even the well-formed default
/// expression `"${user.language:en}-${user.country:}"` (often
/// rendered as `"en-"` when user.country is unset) is rejected during
/// Quarkus config validation, blocking Keycloak boot.
///
/// Mirror the validator's intent leniently: split on `-` / `_`, treat
/// `null` / empty as null, treat `"all"` as `Locale.ROOT`, otherwise
/// construct `new Locale(language, country)` via the JDK constructor —
/// good enough for downstream consumers that read language/country
/// directly.
fn essential_quarkus_locale_convert(
    ctx: &mut dyn NativeContext,
    args: &[Value],
) -> MethodCallResult {
    let s_obj = match args.get(1) {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Object(None))),
    };
    let raw = ctx.read_string(s_obj).unwrap_or_default();
    let trimmed = raw.trim();
    if trimmed.is_empty() {
        return Ok(Some(Value::Object(None)));
    }
    if trimmed == "all" {
        // B2 fix: "all" maps to Locale.ROOT (the empty locale), NOT the host's
        // default locale. `Locale.ROOT` is equivalent to `new Locale("", "")`
        // (empty language/country/variant), so build it via the constructor
        // rather than returning getDefault() (which would leak e.g. en_US).
        let cls = "java/util/Locale";
        let loc_obj = match ctx.new_object(cls) {
            Ok(Some(Value::Object(Some(o)))) => o,
            _ => return Ok(Some(Value::Object(None))),
        };
        // Pin across the create_string + <init> below — a moving young GC
        // there would relocate loc_obj out from under this raw Rust local
        // (native stale-local family).
        let loc_pin = ctx.pin_native_root(loc_obj);
        let empty = ctx.create_string("");
        let loc_cur = ctx.read_native_pin(loc_pin, loc_obj);
        let _ = ctx.invoke(
            cls,
            "<init>",
            "(Ljava/lang/String;Ljava/lang/String;Ljava/lang/String;)V",
            &[
                Value::Object(Some(loc_cur)),
                Value::Object(Some(empty)),
                Value::Object(Some(empty)),
                Value::Object(Some(empty)),
            ],
        );
        let loc_cur = ctx.read_native_pin(loc_pin, loc_obj);
        ctx.unpin_native_roots(loc_pin);
        return Ok(Some(Value::Object(Some(loc_cur))));
    }
    // Normalise: replace '_' with '-' then split.
    let normalised: String = trimmed.replace('_', "-");
    let mut parts = normalised.split('-');
    let lang = parts.next().unwrap_or("").to_string();
    let country = parts.next().unwrap_or("").to_string();
    let variant = parts.next().unwrap_or("").to_string();
    // Construct via Locale's (String,String,String) constructor — works
    // regardless of `forLanguageTag`'s CLDR-data dependencies.
    let cls = "java/util/Locale";
    let loc_obj = match ctx.new_object(cls) {
        Ok(Some(Value::Object(Some(o)))) => o,
        _ => return Ok(Some(Value::Object(None))),
    };
    // Pin every ref held across the later create_string/<init> allocations —
    // a moving young GC there would relocate them out from under these raw
    // Rust locals (native stale-local family). `v` is used immediately with
    // no intervening allocation, so it needs no pin.
    let loc_pin = ctx.pin_native_root(loc_obj);
    let l = ctx.create_string(&lang);
    let l_pin = ctx.pin_native_root(l);
    let c = ctx.create_string(&country);
    let c_pin = ctx.pin_native_root(c);
    let v = ctx.create_string(&variant);
    let loc_cur = ctx.read_native_pin(loc_pin, loc_obj);
    let l_cur = ctx.read_native_pin(l_pin, l);
    let c_cur = ctx.read_native_pin(c_pin, c);
    let _ = ctx.invoke(
        cls,
        "<init>",
        "(Ljava/lang/String;Ljava/lang/String;Ljava/lang/String;)V",
        &[
            Value::Object(Some(loc_cur)),
            Value::Object(Some(l_cur)),
            Value::Object(Some(c_cur)),
            Value::Object(Some(v)),
        ],
    );
    let loc_cur = ctx.read_native_pin(loc_pin, loc_obj);
    ctx.unpin_native_roots(loc_pin);
    Ok(Some(Value::Object(Some(loc_cur))))
}

/// Decode `java.lang.String` used as a system/property key when
/// `NativeContext::read_string` yields empty (compact `String` layout edge cases).
pub(crate) fn property_key_from_java_string(
    ctx: &mut dyn NativeContext,
    key_obj: ObjectRef,
) -> String {
    let s = normalize_java_property_key(&ctx.read_string(key_obj).unwrap_or_default());
    if !s.is_empty() {
        return s;
    }
    let Value::Object(Some(arr)) = ctx.get_field_by_name(key_obj, "value") else {
        return String::new();
    };
    if ctx.heap_element_type_of(arr) != cratonvm_types::ArrayElementType::Byte {
        return String::new();
    }
    let coder = match ctx.get_field_by_name(key_obj, "coder") {
        Value::Int(c) => c,
        _ => 0,
    };
    let len = ctx.array_length(arr);
    if coder != 0 {
        if len % 2 != 0 {
            return String::new();
        }
        let num_units = len / 2;
        let mut utf16 = Vec::with_capacity(num_units);
        for i in 0..num_units {
            // Little-endian: low byte at even index, high byte at odd index
            // (matches StringUTF16.isBigEndian()==false on x86/ARM).
            let lo = match ctx.get_array_element(arr, i * 2) {
                Value::Int(v) => (v & 0xFF) as u16,
                _ => 0,
            };
            let hi = match ctx.get_array_element(arr, i * 2 + 1) {
                Value::Int(v) => (v & 0xFF) as u16,
                _ => 0,
            };
            utf16.push((hi << 8) | lo);
        }
        return String::from_utf16_lossy(&utf16);
    }
    let mut out = String::with_capacity(len);
    for i in 0..len {
        let b = match ctx.get_array_element(arr, i) {
            Value::Int(v) => (v & 0xFF) as u8,
            _ => 0,
        };
        out.push(b as char);
    }
    normalize_java_property_key(&out)
}

fn native_wildfly_security_manager_get_property_privileged(
    ctx: &mut dyn NativeContext,
    args: &[Value],
) -> MethodCallResult {
    let default = args.get(1).copied().unwrap_or(Value::Object(None));
    let key_obj = match args.first() {
        Some(Value::Object(Some(k))) => *k,
        _ => return Ok(Some(default)),
    };
    let key = property_key_from_java_string(ctx, key_obj);
    match ctx
        .get_system_property(&key)
        .or_else(|| system_property_fallback(ctx, &key))
    {
        Some(v) => Ok(Some(Value::Object(Some(ctx.create_string(&v))))),
        None => Ok(Some(default)),
    }
}

