// ---------------------------------------------------------------------------
// Context ClassLoader storage (Thread.get/setContextClassLoader)
// ---------------------------------------------------------------------------

use std::sync::Mutex;
use std::sync::OnceLock;

// GC note (gc-followups-20260706): VESTIGIAL — `set_context_class_loader` has
// no callers, so this slot is never populated and `get_context_class_loader`
// always returns `None` (the natives below read the Thread's
// `contextClassLoader` FIELD, which the GC traces/remaps normally). GC-safe
// only because it is never written; if a writer is ever added, convert to the
// `(identity_key, ObjectRef)` var-handle-root pattern (see ASYNC_POOL) first.
fn context_class_loader_store() -> &'static Mutex<Option<ObjectRef>> {
    static INSTANCE: OnceLock<Mutex<Option<ObjectRef>>> = OnceLock::new();
    INSTANCE.get_or_init(|| Mutex::new(None))
}

fn set_context_class_loader(loader: Option<ObjectRef>) {
    *context_class_loader_store()
        .lock()
        .unwrap_or_else(|e| e.into_inner()) = loader;
}

fn get_context_class_loader() -> Option<ObjectRef> {
    *context_class_loader_store()
        .lock()
        .unwrap_or_else(|e| e.into_inner())
}

fn explicit_null_context_class_loader_store() -> &'static Mutex<std::collections::HashSet<i32>> {
    static INSTANCE: OnceLock<Mutex<std::collections::HashSet<i32>>> = OnceLock::new();
    INSTANCE.get_or_init(|| Mutex::new(std::collections::HashSet::new()))
}

fn set_thread_context_loader_explicit_null(
    ctx: &dyn NativeContext,
    thread: ObjectRef,
    explicit_null: bool,
) {
    let key = ctx.identity_hash_code(thread);
    let mut guard = explicit_null_context_class_loader_store()
        .lock()
        .unwrap_or_else(|e| e.into_inner());
    if explicit_null {
        guard.insert(key);
    } else {
        guard.remove(&key);
    }
}

fn thread_context_loader_is_explicit_null(ctx: &dyn NativeContext, thread: ObjectRef) -> bool {
    let key = ctx.identity_hash_code(thread);
    explicit_null_context_class_loader_store()
        .lock()
        .unwrap_or_else(|e| e.into_inner())
        .contains(&key)
}

fn native_thread_set_context_class_loader(
    ctx: &mut dyn NativeContext,
    args: &[Value],
) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(None),
    };
    let loader = args.get(1).copied().unwrap_or(Value::Object(None));
    set_thread_context_loader_explicit_null(ctx, this, matches!(loader, Value::Object(None)));
    ctx.set_field_by_name(this, "contextClassLoader", loader);
    Ok(None)
}

fn native_thread_get_context_class_loader(
    ctx: &mut dyn NativeContext,
    args: &[Value],
) -> MethodCallResult {
    if let Some(Value::Object(Some(this))) = args.first() {
        match ctx.get_field_by_name(*this, "contextClassLoader") {
            Value::Object(Some(loader)) => {
                // A stale/mis-slotted Thread field can contain an unrelated
                // heap object (observed as String.findResources during
                // Mockito plugin discovery). Never expose that as a loader:
                // Java callers immediately virtual-dispatch on the result.
                // Do not route this check through `Class.isInstance`: during
                // early real-JDK bootstrap its mirror metadata can be stale
                // enough to admit a String.  The VM's actual class hierarchy
                // is the authoritative type relation here.
                let is_loader = ctx
                    .class_id_by_name("java/lang/ClassLoader")
                    .map(|loader_class_id| {
                        let actual_class_id = ctx.class_id_of_object(loader);
                        actual_class_id == loader_class_id
                            || ctx.is_subclass(actual_class_id, loader_class_id)
                    })
                    .unwrap_or(false);
                if is_loader {
                    return Ok(Some(Value::Object(Some(loader))));
                }
            }
            _ => {
                if thread_context_loader_is_explicit_null(ctx, *this) {
                    return Ok(Some(Value::Object(None)));
                }
            }
        }
    }
    if let Some(loader) = get_context_class_loader() {
        return Ok(Some(Value::Object(Some(loader))));
    }
    let obj = crate::classloader::get_or_create_app_loader(ctx);
    Ok(Some(Value::Object(Some(obj))))
}

#[cfg(test)]
mod context_class_loader_tests {
    use super::*;
    use crate::test_utils::mock_ctx;

    #[test]
    fn explicit_null_context_class_loader_round_trips() {
        let mut ctx = mock_ctx();
        let thread = ctx.fresh_object_ref();

        native_thread_set_context_class_loader(
            &mut ctx,
            &[Value::Object(Some(thread)), Value::Object(None)],
        )
        .expect("setContextClassLoader(null) should not throw");

        let got = native_thread_get_context_class_loader(&mut ctx, &[Value::Object(Some(thread))])
            .expect("getContextClassLoader should not throw");
        assert_eq!(got, Some(Value::Object(None)));
    }

    #[test]
    fn essential_registers_netty_event_executor_shutdown_bridge() {
        let mut registry = NativeMethodRegistry::new();
        register_essential_natives(&mut registry);
        for class_name in [
            "io/netty/util/concurrent/EventExecutorGroup",
            "io/netty/util/concurrent/AbstractEventExecutorGroup",
            "io/netty/channel/MultiThreadIoEventLoopGroup",
        ] {
            assert!(registry
                .find(
                    class_name,
                    "shutdownGracefully",
                    "()Lio/netty/util/concurrent/Future;"
                )
                .is_some());
        }
    }

    #[test]
    fn essential_define_class2_registration_uses_bytebuffer_handler() {
        let mut registry = NativeMethodRegistry::new();
        register_essential_natives(&mut registry);
        let callback = registry
            .find(
                "java/lang/ClassLoader",
                "defineClass2",
                "(Ljava/lang/ClassLoader;Ljava/lang/String;Ljava/nio/ByteBuffer;IILjava/security/ProtectionDomain;Ljava/lang/String;)Ljava/lang/Class;",
            )
            .expect("defineClass2 native should be registered");

        let mut ctx = mock_ctx();
        let bytes = ctx.new_array(cratonvm_types::ArrayElementType::Byte, 4);
        let bb = ctx.alloc_object(cratonvm_types::ClassId::new(0), 4);
        ctx.set_field(bb, 0, Value::Object(Some(bytes)));
        ctx.set_field(bb, 1, Value::Int(0));
        ctx.set_field(bb, 2, Value::Int(4));
        ctx.set_field(bb, 3, Value::Int(4));
        let name = ctx.create_string("com/example/Foo");

        let result = callback(
            &mut ctx,
            &[
                Value::Object(None),
                Value::Object(Some(name)),
                Value::Object(Some(bb)),
                Value::Int(0),
                Value::Int(4),
                Value::Object(None),
                Value::Object(None),
            ],
        );

        match result {
            Err(cratonvm_types::error::MethodCallFailed::InternalError(
                cratonvm_types::error::VmError::Linkage(
                    cratonvm_types::error::LinkageError::ClassFormatError { message, .. },
                ),
            )) => assert!(
                message.contains("defineClass2"),
                "expected defineClass2 ByteBuffer handler failure, got {message}"
            ),
            other => panic!("defineClass2 did not dispatch to the ByteBuffer handler: {other:?}"),
        }
    }

    #[test]
    fn essential_natives_include_real_jdk_symbol_lookup_bridge() {
        let mut registry = NativeMethodRegistry::new();
        register_essential_natives(&mut registry);
        let sl = "java/lang/foreign/SymbolLookup";

        assert!(registry
            .find(sl, "find", "(Ljava/lang/String;)Ljava/util/Optional;")
            .is_some());
        assert!(registry
            .find(
                sl,
                "libraryLookup",
                "(Ljava/lang/String;Ljava/lang/foreign/Arena;)Ljava/lang/foreign/SymbolLookup;",
            )
            .is_some());
        assert!(registry
            .find(sl, "loaderLookup", "()Ljava/lang/foreign/SymbolLookup;")
            .is_some());
    }

    #[test]
    fn essential_natives_include_stamped_lock_view_unlock_bridges() {
        let mut registry = NativeMethodRegistry::new();
        register_essential_natives(&mut registry);
        let stamped_lock = "java/util/concurrent/locks/StampedLock";

        assert!(registry
            .find(stamped_lock, "unstampedUnlockWrite", "()V")
            .is_some());
        assert!(registry
            .find(stamped_lock, "unstampedUnlockRead", "()V")
            .is_some());
    }

    #[test]
    fn essential_natives_include_jdk17_stacktraceelements_bridge() {
        let mut registry = NativeMethodRegistry::new();
        register_essential_natives(&mut registry);
        let ste = "java/lang/StackTraceElement";

        assert!(registry
            .find(
                ste,
                "initStackTraceElements",
                "([Ljava/lang/StackTraceElement;Ljava/lang/Object;I)V",
            )
            .is_some());
        assert!(registry
            .find(
                ste,
                "initStackTraceElements",
                "([Ljava/lang/StackTraceElement;Ljava/lang/Throwable;)V",
            )
            .is_some());
    }

    #[cfg(feature = "experimental-serialization")]
    #[test]
    fn essential_registers_reflection_factory_serialization_hooks() {
        let mut registry = NativeMethodRegistry::new();
        register_essential_natives(&mut registry);

        assert!(registry
            .find(
                "sun/reflect/ReflectionFactory",
                "readObjectForSerialization",
                "(Ljava/lang/Class;)Ljava/lang/invoke/MethodHandle;"
            )
            .is_some());
        assert!(registry
            .find(
                "sun/reflect/ReflectionFactory",
                "getReflectionFactory",
                "()Lsun/reflect/ReflectionFactory;"
            )
            .is_some());
    }
}

// ---------------------------------------------------------------------------
// Reference / ReferenceQueue field layout constants
// These are used by essential natives for java.lang.ref.* handling.
// ---------------------------------------------------------------------------

/// Reference layout: field 0 = referent (Object or null), field 1 = queue
pub(crate) const REF_FIELD_REFERENT: usize = 0;
pub(crate) const REF_FIELD_QUEUE: usize = 1;
/// Real-JDK `java.lang.ref.Reference` layout slot 2: the `next` field
/// (queue linkage). References with fewer than 3 fields (legacy synthetic
/// shape) fall back to referent-slot linkage — see
/// `reference::ref_next_slot`.
pub(crate) const REF_FIELD_NEXT: usize = 2;

/// ReferenceQueue layout: field 0 = head of linked list, field 1 = size
pub(crate) const RQ_FIELD_HEAD: usize = 0;
pub(crate) const RQ_FIELD_SIZE: usize = 1;

/// Register PrintStream/PrintWriter fallback natives.
///
/// These override the real JDK bytecode implementations so our synthetic
/// System.out/System.err streams (1-field objects) work correctly in real JDK
/// mode, particularly when System.initPhase1() has not completed successfully.
/// The fallbacks simply write to the host process stdout/stderr via fd_table.
fn register_printstream_fallback_natives(registry: &mut NativeMethodRegistry) {
    // census-tag: PrintStream/PrintWriter natives bridge host stdout/stderr.
    let __prev_cat = registry.current_category();
    registry.set_category(cratonvm_native_api::NativeKind::Bridge);
    registry.register(
        "java/io/PrintStream",
        "<init>",
        "(Ljava/io/OutputStream;)V",
        native_printstream_init_outputstream,
    );
    registry.register(
        "java/io/PrintStream",
        "<init>",
        "(Ljava/io/OutputStream;Z)V",
        native_printstream_init_outputstream,
    );
    registry.register(
        "java/io/PrintStream",
        "println",
        "(Ljava/lang/String;)V",
        native_println_string,
    );
    registry.register("java/io/PrintStream", "println", "(I)V", native_println_int);
    registry.register(
        "java/io/PrintStream",
        "println",
        "(J)V",
        native_println_long,
    );
    registry.register(
        "java/io/PrintStream",
        "println",
        "(D)V",
        native_println_double,
    );
    registry.register(
        "java/io/PrintStream",
        "println",
        "(Z)V",
        native_println_boolean,
    );
    registry.register(
        "java/io/PrintStream",
        "println",
        "(C)V",
        native_println_char,
    );
    registry.register(
        "java/io/PrintStream",
        "println",
        "(F)V",
        native_println_float,
    );
    registry.register("java/io/PrintStream", "println", "()V", native_println_void);
    registry.register(
        "java/io/PrintStream",
        "println",
        "(Ljava/lang/Object;)V",
        native_println_object,
    );
    registry.register(
        "java/io/PrintStream",
        "print",
        "(Ljava/lang/String;)V",
        native_print_string,
    );
    registry.register("java/io/PrintStream", "print", "(I)V", native_print_int);
    registry.register("java/io/PrintStream", "print", "(C)V", native_print_char);
    registry.register("java/io/PrintStream", "print", "(Z)V", native_print_boolean);
    registry.register("java/io/PrintStream", "print", "(J)V", native_print_long);
    registry.register("java/io/PrintStream", "print", "(F)V", native_print_float);
    registry.register("java/io/PrintStream", "print", "(D)V", native_print_double);
    registry.register(
        "java/io/PrintStream",
        "print",
        "(Ljava/lang/Object;)V",
        native_print_object,
    );
    registry.register(
        "java/io/PrintStream",
        "printf",
        "(Ljava/lang/String;[Ljava/lang/Object;)Ljava/io/PrintStream;",
        native_printf,
    );
    registry.register(
        "java/io/PrintStream",
        "format",
        "(Ljava/lang/String;[Ljava/lang/Object;)Ljava/io/PrintStream;",
        native_printf,
    );
    // PrintStream writer-path entries. JUnit's ConsoleLauncher wraps
    // `System.out` (a PrintStream) in a `PrintWriter`; `PrintWriter.write`
    // delegates `out.write(String,int,int)` straight onto the PrintStream
    // receiver. The real JDK PrintStream only has a package-private
    // `write(String)` and no 3-arg form, so without these natives the
    // launcher aborts with `NoSuchMethodError: PrintStream.write(String,II)V`.
    registry.register(
        "java/io/PrintStream",
        "write",
        "([BII)V",
        native_printstream_write,
    );
    registry.register(
        "java/io/PrintStream",
        "write",
        "(I)V",
        native_printstream_write_int,
    );
    registry.register(
        "java/io/PrintStream",
        "write",
        "(Ljava/lang/String;)V",
        native_printstream_write_string,
    );
    registry.register(
        "java/io/PrintStream",
        "write",
        "(Ljava/lang/String;II)V",
        native_printstream_write_string_range,
    );
    registry.register(
        "java/io/PrintStream",
        "append",
        "(Ljava/lang/CharSequence;)Ljava/io/PrintStream;",
        native_printstream_append,
    );
    // Our System.out/err are fd-backed synthetic PrintStreams (slot 0 = fd
    // id); their inherited FilterOutputStream `out` field is never populated.
    // The real-JDK `PrintStream.flush()`/`close()` bytecode dereferences that
    // null `out` (`out.flush()`) → NPE ("Cannot invoke flush on null") for any
    // program that calls `System.out.flush()`. Route both through the fd-aware
    // natives instead: flush drains the fd's buffer, close is a no-op (we must
    // never close the process stdout/stderr). Mirrors the synthetic-mode
    // PrintStream registration and the long-standing fd-stream flush contract.
    registry.register(
        "java/io/PrintStream",
        "flush",
        "()V",
        native_printstream_flush,
    );
    registry.register(
        "java/io/PrintStream",
        "close",
        "()V",
        native_printstream_close,
    );
    // PrintWriter — use dedicated variants that route through the underlying
    // Writer when the backing is non-fd (e.g. StringWriter in ModelNode.toString()).
    registry.register(
        "java/io/PrintWriter",
        "write",
        "(Ljava/lang/String;II)V",
        native_printwriter_write_string_range,
    );
    registry.register(
        "java/io/PrintWriter",
        "write",
        "(Ljava/lang/String;)V",
        native_printwriter_write_string,
    );
    registry.register(
        "java/io/PrintWriter",
        "println",
        "(Ljava/lang/String;)V",
        native_println_string,
    );
    registry.register("java/io/PrintWriter", "println", "()V", native_println_void);
    registry.register("java/io/PrintWriter", "println", "(I)V", native_println_int);
    registry.register(
        "java/io/PrintWriter",
        "println",
        "(Ljava/lang/Object;)V",
        native_println_object,
    );
    // Single-arg `PrintWriter(OutputStream)` — JDK chains to
    // `PrintWriter(OutputStream, boolean)` with `autoFlush=false`.  JUnit's
    // ConsoleLauncher invokes this twice during startup (wrapping stdout
    // and stderr); without an explicit native, real-JDK dispatch fails to
    // resolve the constructor and the launcher silently aborts with zero
    // tests run.
    registry.register(
        "java/io/PrintWriter",
        "<init>",
        "(Ljava/io/OutputStream;)V",
        native_printwriter_init_outputstream,
    );
    registry.set_category(__prev_cat);
}

std::thread_local! {
    /// Guards nested `URL.setURLStreamHandlerFactory` installs (Spring Boot 3.x
    /// / insurance) that recurse through class-init while the outer call is
    /// still unwinding — matching JDK "single install" semantics without
    /// letting JDK bytecode re-enter unbounded.
    static URL_SET_STREAM_HANDLER_FACTORY_DEPTH: std::cell::Cell<u32> = std::cell::Cell::new(0);
}

fn native_url_set_stream_handler_factory_guard(
    ctx: &mut dyn NativeContext,
    args: &[Value],
) -> MethodCallResult {
    let d = URL_SET_STREAM_HANDLER_FACTORY_DEPTH.get();
    if d != 0 {
        // Re-entrant install (Spring Boot's factory recurses through
        // class-init while the outer call is still unwinding). The JDK would
        // throw `Error("factory already defined")`; we swallow it to keep the
        // single, outermost factory — matching "first install wins" for the
        // nested case.
        return Ok(None);
    }
    URL_SET_STREAM_HANDLER_FACTORY_DEPTH.set(1);
    // `setURLStreamHandlerFactory` is a *static* method, so `args[0]` is the
    // factory itself (no receiver). Publish it into the real `java.net.URL`
    // static `factory` field so the un-intercepted real `getURLStreamHandler`
    // bytecode consults it. Without this the field stays null and
    // `new URL("vfszip:...")` (Hibernate JarVisitorTest, Spring Boot loader)
    // raises `MalformedURLException: unknown protocol`. The real JDK also
    // clears the `handlers` cache on install; we leave it — a freshly-booted
    // VM has nothing cached for an app-defined scheme.
    if let Some(Value::Object(Some(fac))) = args.first() {
        // Force-native dispatch (force_native_over_real_jdk_bytecode) runs this
        // guard as the body of `setURLStreamHandlerFactory` WITHOUT first
        // running `java/net/URL`'s `<clinit>` (the normal invokestatic
        // class-init step is skipped for the override). If we publish `factory`
        // before URL is initialized, URL's later initialization re-creates its
        // statics vector and silently discards our write — leaving `factory`
        // null so `getURLStreamHandler` never consults the app factory
        // (`MalformedURLException: unknown protocol: classpath`, Tomcat
        // TestConfigFileLoader / TestClasspathUrlStreamHandler). Initialize URL
        // FIRST so the static store exists and is stable, then publish into it.
        let _ = ctx.ensure_class_initialized("java/net/URL");
        ctx.set_static_field_by_name("java/net/URL", "factory", Value::Object(Some(*fac)));
    }
    URL_SET_STREAM_HANDLER_FACTORY_DEPTH.set(0);
    Ok(None)
}

fn native_urlconnection_set_content_handler_factory(
    ctx: &mut dyn NativeContext,
    args: &[Value],
) -> MethodCallResult {
    if let Some(Value::Object(Some(fac))) = args.first() {
        let _ = ctx.ensure_class_initialized("java/net/URLConnection");
        ctx.set_static_field_by_name(
            "java/net/URLConnection",
            "factory",
            Value::Object(Some(*fac)),
        );
    }
    Ok(None)
}

fn native_permissions_add(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(None),
    };
    let permission = args.get(1).copied().unwrap_or(Value::Object(None));
    if native_permissions_is_read_only(ctx, &[Value::Object(Some(this))])?
        .and_then(|v| v.as_int())
        .unwrap_or(0)
        != 0
    {
        return Err(RuntimeError::SecurityException {
            message: "attempt to add to readonly PermissionCollection".to_string(),
        }
        .into());
    }
    if let Some(slot) = ctx.resolve_field_index("java/security/Permissions", "allPermission") {
        ctx.set_field(this, slot, permission);
    } else {
        ctx.set_field(this, 0, permission);
    }
    Ok(None)
}

fn native_permissions_set_read_only(
    ctx: &mut dyn NativeContext,
    args: &[Value],
) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(None),
    };
    if let Some(slot) = ctx.resolve_field_index("java/security/PermissionCollection", "readOnly") {
        ctx.set_field(this, slot, Value::Int(1));
    } else {
        // Synthetic Permissions objects are allocated with slot 1 as the
        // read-only flag by security_manager.rs helpers.
        ctx.set_field(this, 1, Value::Int(1));
    }
    Ok(None)
}

fn native_permissions_is_read_only(
    ctx: &mut dyn NativeContext,
    args: &[Value],
) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Int(0))),
    };
    if let Some(slot) = ctx.resolve_field_index("java/security/PermissionCollection", "readOnly") {
        return Ok(Some(Value::Int(
            ctx.get_field(this, slot).as_int().unwrap_or(0),
        )));
    }
    Ok(Some(Value::Int(
        ctx.get_field(this, 1).as_int().unwrap_or(0),
    )))
}

/// `ObjectStreamClass.hasStaticInitializer(Class[, boolean]) -> boolean`:
/// true iff the class declares a `<clinit>`. Always-compiled mirror of
/// `serialization::class_has_static_initializer` (+ its `class_id_of_mirror`
/// synthetic-jdk fallback) so the ESSENTIAL registration below does not depend
/// on the feature-gated `serialization` module — otherwise
/// `cargo test -p cratonvm-native-builtins` (built without
/// `experimental-serialization`) fails to compile. Behaviour matches the gated
/// path; `serialization.rs` keeps its own copy for the feature-on build.
fn essential_class_has_static_initializer(ctx: &mut dyn NativeContext, args: &[Value]) -> bool {
    let mirror = match args.first() {
        Some(Value::Object(Some(m))) => *m,
        _ => return false,
    };
    let class_id = ctx.class_id_from_mirror(mirror).or_else(|| {
        // Synthetic-jdk fallback: read the mirror's "name" field, look up by name.
        if let Value::Object(Some(s)) = ctx.get_field_by_name(mirror, "name") {
            if let Some(n) = ctx.read_string(s) {
                return ctx.class_id_by_name(&n.replace('.', "/"));
            }
        }
        None
    });
    match class_id {
        Some(id) => ctx
            .declared_methods(id)
            .iter()
            .any(|m| &*m.name == "<clinit>"),
        None => false,
    }
}

/// True when `obj`'s concrete class is `java.util.logging.Logger$ConfigurationData`.
///
/// Used by the `java/util/logging/Logger.{get,set}Level` natives to tell a
/// **real-JDK** `Logger` apart from the flat synthetic loggers our own
/// `getLogger` natives mint. A real `Logger` keeps its level in
/// `config.levelObject` (where `config` is a `ConfigurationData`); the
/// synthetic loggers instead stash the name in slot 0 — which is the real
/// `config` field slot — so for them `config` resolves to a `String`, not a
/// `ConfigurationData`. Only the real shape is written/read through; synthetic
/// loggers keep their historic no-op/null level behaviour (their effective
/// level is governed by the process-wide tracing subscriber).
fn jul_logger_config_is_real(ctx: &mut dyn NativeContext, obj: ObjectRef) -> bool {
    ctx.class_name_of_id(ctx.class_id_of_object(obj))
        .map(|n| n == "java/util/logging/Logger$ConfigurationData")
        .unwrap_or(false)
}

/// GC-safe side table for `java.util.logging.Logger`'s handler list, keyed by
/// `identity_hash_code` (same pattern as `net_phase_e.rs`'s `ss_side_table` /
/// `stream_owner_table`). `addHandler`/`removeHandler`/`getHandlers` are
/// fully native-overridden (never fall through to real bytecode), so they
/// don't need to live in any particular instance field slot -- and MUST NOT,
/// because real-JDK 25's `Logger` has no `handlers` instance field at all
/// (handlers moved inside `Logger$ConfigurationData`, referenced from slot 0
/// / `config`) and slot 2 is actually `name` (a `String`). The old code
/// stored/read the handler `ArrayList` at raw field slot 2, which on a
/// real-bytecode-constructed `Logger` collided with `name`:
/// `ctx.invoke_virtual(nameString, "size", "()I", ...)` then threw
/// `NoSuchMethodError: java/lang/String.size()I` (surfaced from
/// `org.apache.juli.ClassLoaderLogManager.resetLoggers`, which calls
/// `logger.getHandlers()` during webapp/classloader shutdown -- see
/// docs/known-issues/tomcat-08-07/largeclienthello-string-size-nosuchmethod.md).
/// Keying by identity hash and holding the list as a global GC root
/// sidesteps field layout entirely -- correct for both real and synthetic
/// loggers, and immune to future real-JDK field-order changes.
fn jul_logger_handlers_table() -> &'static std::sync::Mutex<std::collections::HashMap<i32, usize>> {
    static T: OnceLock<std::sync::Mutex<std::collections::HashMap<i32, usize>>> = OnceLock::new();
    T.get_or_init(|| std::sync::Mutex::new(std::collections::HashMap::new()))
}

pub(crate) fn jul_logger_handlers_get(
    ctx: &mut dyn NativeContext,
    logger: ObjectRef,
) -> Option<ObjectRef> {
    let key = ctx.identity_hash_code(logger);
    let handle = *jul_logger_handlers_table().lock().unwrap().get(&key)?;
    ctx.resolve_global_root(handle)
}

pub(crate) fn jul_logger_handlers_set(
    ctx: &mut dyn NativeContext,
    logger: ObjectRef,
    list: ObjectRef,
) {
    let handle = ctx.add_global_root(list);
    let key = ctx.identity_hash_code(logger);
    jul_logger_handlers_table()
        .lock()
        .unwrap()
        .insert(key, handle);
}

pub(crate) fn jul_logger_handlers_clear(ctx: &mut dyn NativeContext, logger: ObjectRef) {
    let key = ctx.identity_hash_code(logger);
    if let Some(handle) = jul_logger_handlers_table().lock().unwrap().remove(&key) {
        ctx.remove_global_root(handle);
    }
}

