fn antlr_common_token_pair_field(ctx: &dyn NativeContext, token: ObjectRef, field: &str) -> Value {
    match ctx.get_field_by_name(token, "source") {
        Value::Object(Some(source)) => ctx.get_field_by_name(source, field),
        _ => Value::Object(None),
    }
}

