/// Exception <init>(Ljava/lang/String;)V — sets detailMessage (field 0)
/// Exception <init>(Ljava/lang/String;Ljava/lang/Throwable;)V
/// Exception <init>(Ljava/lang/Throwable;)V — sets cause (field 1)
pub(crate) fn native_return_false(
    _ctx: &mut dyn NativeContext,
    _args: &[Value],
) -> MethodCallResult {
    Ok(Some(Value::Int(0))) // false
}

/// Default JVM-wide assertion status reported by `Class.desiredAssertionStatus`
/// / `desiredAssertionStatus0`. Real HotSpot returns `false` unless `-ea` is on;
/// CratonVM mirrors that, but honours `CRATONVM_ENABLE_ASSERTIONS=1` so test
/// harnesses can reproduce Surefire's default (Surefire forks the test JVM with
/// `-ea`). When enabled, `<clinit>` stores `$assertionsDisabled = false`, so
/// `assert` statements in real bytecode (e.g. keycloak JWKUtil.toIntegerBytes)
/// actually throw `AssertionError` on violation instead of being no-ops.
pub(crate) fn assertion_status_default() -> i32 {
    if std::env::var_os("CRATONVM_ENABLE_ASSERTIONS").is_some() {
        1
    } else {
        0
    }
}

/// `Class.desiredAssertionStatus0(Class)` / `desiredAssertionStatus()` honouring
/// the `CRATONVM_ENABLE_ASSERTIONS` flag — see [`assertion_status_default`].
pub(crate) fn native_assertion_status(
    _ctx: &mut dyn NativeContext,
    _args: &[Value],
) -> MethodCallResult {
    Ok(Some(Value::Int(assertion_status_default())))
}

pub(crate) fn native_return_zero(
    _ctx: &mut dyn NativeContext,
    _args: &[Value],
) -> MethodCallResult {
    Ok(Some(Value::Int(0)))
}

/// Extract ObjectRef from args at given index, or return NullPointerException
/// Map a bare library name (e.g. "foo") to the platform-specific filename
/// (e.g. "foo.dll" on Windows, "libfoo.so" on Linux).
/// If the name already contains a path separator or an extension, it is returned as-is.
pub(crate) fn platform_lib_name(name: &str) -> String {
    if name.contains('/') || name.contains('\\') || name.contains('.') {
        return name.to_string();
    }
    if cfg!(windows) {
        format!("{}.dll", name)
    } else if cfg!(target_os = "macos") {
        format!("lib{}.dylib", name)
    } else {
        format!("lib{}.so", name)
    }
}

fn native_netty_event_executor_group_shutdown_gracefully(
    ctx: &mut dyn NativeContext,
    args: &[Value],
) -> MethodCallResult {
    let this = obj_arg(args, 0)?;
    let class_name = ctx.class_name_of_id(ctx.class_id_of_object(this));
    if class_name.as_deref() != Some("io/netty/channel/MultiThreadIoEventLoopGroup") {
        return ctx.invoke_virtual_bytecode_only(
            this,
            "shutdownGracefully",
            "()Lio/netty/util/concurrent/Future;",
            &[],
        );
    }

    let time_unit = ctx.ensure_class_initialized("java/util/concurrent/TimeUnit")?;
    let milliseconds_field = ctx
        .static_field_index_by_name(time_unit, "MILLISECONDS")
        .ok_or_else(|| {
            MethodCallFailed::InternalError(VmError::Internal {
                message: "java/util/concurrent/TimeUnit.MILLISECONDS static field not found"
                    .to_string(),
            })
        })?;
    let milliseconds = ctx.get_static_field(time_unit, milliseconds_field);
    ctx.invoke_virtual_bytecode_only(
        this,
        "shutdownGracefully",
        "(JJLjava/util/concurrent/TimeUnit;)Lio/netty/util/concurrent/Future;",
        &[Value::Long(0), Value::Long(0), milliseconds],
    )
}

fn native_springboot_mongo_reactive_customizer_destroy(
    ctx: &mut dyn NativeContext,
    args: &[Value],
) -> MethodCallResult {
    let this = obj_arg(args, 0)?;
    // Spring Boot 4.0's customizer blocks here in
    // `shutdownGracefully().awaitUninterruptibly()`. In this runtime Netty's
    // worker threads can already have exited while its promise remains
    // incomplete, leaving application-context destruction stuck forever.
    // Request the ordinary zero-quiet-period graceful shutdown, but do not
    // await its stale termination promise. The matching `customize` bridge
    // creates this one lifecycle-owned group with daemon workers, so those
    // workers cannot retain the VM after the Spring context has returned.
    if let Value::Object(Some(event_loop_group)) = ctx.get_field_by_name(this, "eventLoopGroup") {
        native_netty_event_executor_group_shutdown_gracefully(
            ctx,
            &[Value::Object(Some(event_loop_group))],
        )?;
        ctx.set_field_by_name(this, "eventLoopGroup", Value::Object(None));
    }
    Ok(None)
}

fn native_springboot_mongo_reactive_customizer_customize(
    ctx: &mut dyn NativeContext,
    args: &[Value],
) -> MethodCallResult {
    let this = obj_arg(args, 0)?;
    let builder = match args.get(1).copied() {
        Some(Value::Object(Some(builder))) => builder,
        _ => return Ok(None),
    };

    // Preserve Spring Boot's opt-out for user-provided transport settings.
    if let Value::Object(Some(provider)) = ctx.get_field_by_name(this, "settings") {
        if let Some(Value::Object(Some(settings))) =
            ctx.invoke_virtual(provider, "getIfAvailable", "()Ljava/lang/Object;", &[])?
        {
            if matches!(
                ctx.invoke_virtual(
                    settings,
                    "getTransportSettings",
                    "()Lcom/mongodb/connection/TransportSettings;",
                    &[],
                )?,
                Some(Value::Object(Some(_)))
            ) {
                return Ok(None);
            }
        }
    }

    // A TLS-enabled Mongo client can still be completing its asynchronous
    // bootstrap when Spring destroys this bean. Netty's termination promise is
    // then left incomplete by CratonVM even after all useful work is done. Use
    // a daemon factory only for this Spring-owned client group, preserving the
    // normal non-daemon policy for application-managed Netty groups.
    let thread_factory = match ctx.new_object("io/netty/util/concurrent/DefaultThreadFactory")? {
        Some(Value::Object(Some(factory))) => factory,
        _ => return Ok(None),
    };
    let factory_pin = ctx.pin_native_root(thread_factory);
    let pool_name = ctx.create_string("cratonvm-mongo-reactive");
    let pool_name_pin = ctx.pin_native_root(pool_name);
    let factory = ctx.read_native_pin(factory_pin, thread_factory);
    let pool_name = ctx.read_native_pin(pool_name_pin, pool_name);
    ctx.invoke(
        "io/netty/util/concurrent/DefaultThreadFactory",
        "<init>",
        "(Ljava/lang/String;ZI)V",
        &[
            Value::Object(Some(factory)),
            Value::Object(Some(pool_name)),
            Value::Int(1),
            Value::Int(5),
        ],
    )?;
    ctx.unpin_native_roots(pool_name_pin);

    let handler_factory = match ctx.invoke(
        "io/netty/channel/nio/NioIoHandler",
        "newFactory",
        "()Lio/netty/channel/IoHandlerFactory;",
        &[],
    )? {
        Some(Value::Object(Some(handler_factory))) => handler_factory,
        _ => {
            ctx.unpin_native_roots(factory_pin);
            return Ok(None);
        }
    };
    let handler_pin = ctx.pin_native_root(handler_factory);
    let event_loop_group = match ctx.new_object("io/netty/channel/MultiThreadIoEventLoopGroup")? {
        Some(Value::Object(Some(group))) => group,
        _ => {
            ctx.unpin_native_roots(handler_pin);
            ctx.unpin_native_roots(factory_pin);
            return Ok(None);
        }
    };
    let group_pin = ctx.pin_native_root(event_loop_group);
    let event_loop_group = ctx.read_native_pin(group_pin, event_loop_group);
    let thread_factory = ctx.read_native_pin(factory_pin, thread_factory);
    let handler_factory = ctx.read_native_pin(handler_pin, handler_factory);
    ctx.invoke(
        "io/netty/channel/MultiThreadIoEventLoopGroup",
        "<init>",
        "(Ljava/util/concurrent/ThreadFactory;Lio/netty/channel/IoHandlerFactory;)V",
        &[
            Value::Object(Some(event_loop_group)),
            Value::Object(Some(thread_factory)),
            Value::Object(Some(handler_factory)),
        ],
    )?;
    let event_loop_group = ctx.read_native_pin(group_pin, event_loop_group);
    ctx.set_field_by_name(this, "eventLoopGroup", Value::Object(Some(event_loop_group)));
    ctx.unpin_native_roots(group_pin);
    ctx.unpin_native_roots(handler_pin);
    ctx.unpin_native_roots(factory_pin);

    let transport_builder = match ctx.invoke(
        "com/mongodb/connection/TransportSettings",
        "nettyBuilder",
        "()Lcom/mongodb/connection/NettyTransportSettings$Builder;",
        &[],
    )? {
        Some(Value::Object(Some(transport_builder))) => transport_builder,
        _ => return Ok(None),
    };
    let transport_builder_pin = ctx.pin_native_root(transport_builder);
    let event_loop_group = match ctx.get_field_by_name(this, "eventLoopGroup") {
        Value::Object(Some(group)) => group,
        _ => {
            ctx.unpin_native_roots(transport_builder_pin);
            return Ok(None);
        }
    };
    let transport_builder = ctx.read_native_pin(transport_builder_pin, transport_builder);
    ctx.invoke_virtual(
        transport_builder,
        "eventLoopGroup",
        "(Lio/netty/channel/EventLoopGroup;)Lcom/mongodb/connection/NettyTransportSettings$Builder;",
        &[Value::Object(Some(event_loop_group))],
    )?;
    let transport_builder = ctx.read_native_pin(transport_builder_pin, transport_builder);
    let transport_settings = match ctx.invoke_virtual(
        transport_builder,
        "build",
        "()Lcom/mongodb/connection/NettyTransportSettings;",
        &[],
    )? {
        Some(Value::Object(Some(transport_settings))) => transport_settings,
        _ => {
            ctx.unpin_native_roots(transport_builder_pin);
            return Ok(None);
        }
    };
    let transport_settings_pin = ctx.pin_native_root(transport_settings);
    let transport_settings = ctx.read_native_pin(transport_settings_pin, transport_settings);
    ctx.invoke_virtual(
        builder,
        "transportSettings",
        "(Lcom/mongodb/connection/TransportSettings;)Lcom/mongodb/MongoClientSettings$Builder;",
        &[Value::Object(Some(transport_settings))],
    )?;
    ctx.unpin_native_roots(transport_settings_pin);
    ctx.unpin_native_roots(transport_builder_pin);
    Ok(None)
}

fn system_ephemeral_port_range() -> (i32, i32) {
    std::fs::read_to_string("/proc/sys/net/ipv4/ip_local_port_range")
        .ok()
        .and_then(|range| {
            let mut ports = range.split_whitespace().filter_map(|port| port.parse::<i32>().ok());
            Some((ports.next()?, ports.next()?))
        })
        .filter(|(lower, upper)| (0..=*upper).contains(lower) && *upper <= 65_535)
        // IANA's dynamic/private range is the portable fallback when the host
        // has no Linux procfs port-range setting (for example on Windows).
        .unwrap_or((49_152, 65_535))
}

pub(crate) fn obj_arg(
    args: &[Value],
    idx: usize,
) -> Result<ObjectRef, cratonvm_types::error::MethodCallFailed> {
    match args.get(idx) {
        Some(Value::Object(Some(o))) => Ok(*o),
        _ => {
            // RKC16N.9 diagnostic. The "null object argument" NPE is
            // generic across ~3900 obj_arg call sites; without a Java
            // frame at this point we cannot tell *which* native helper
            // is being invoked with a null.
            //
            // When `CRATONVM_DBG_NULL_NATIVE` is set, dump a Rust
            // backtrace + the offending arg index/length to stderr.
            // The topmost non-`obj_arg` frame names the native helper.
            // Gated so production NPEs stay quiet — Java code legally
            // throws NPE in many places (`HashMap.get(null)` etc.) and
            // we don't want to drown those in backtraces.
            if std::env::var_os("CRATONVM_DBG_NULL_NATIVE").is_some() {
                eprintln!(
                    "[obj_arg] null at idx={} args.len={}\n{}",
                    idx,
                    args.len(),
                    std::backtrace::Backtrace::force_capture()
                );
            }
            Err(cratonvm_types::error::RuntimeError::NullPointerException {
                message: Some("null object argument".to_string()),
            }
            .into())
        }
    }
}

pub(crate) fn native_not_implemented(
    _ctx: &mut dyn NativeContext,
    _args: &[Value],
) -> MethodCallResult {
    Err(cratonvm_types::error::MethodCallFailed::InternalError(
        cratonvm_types::error::VmError::Runtime(
            cratonvm_types::error::RuntimeError::NotImplemented {
                feature: "native method not yet implemented".to_string(),
            },
        ),
    ))
}

// ---------------------------------------------------------------------------
// java.lang.Object natives
// ---------------------------------------------------------------------------

fn native_object_hash_code(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    // args[0] = this (the object)
    let this = match args.first() {
        Some(Value::Object(Some(obj_ref))) => *obj_ref,
        _ => {
            return Err(cratonvm_types::error::RuntimeError::NullPointerException {
                message: Some("hashCode on null".to_string()),
            }
            .into());
        }
    };
    // Synthetic generic-reflection stubs (GenericArrayType/ParameterizedType/
    // WildcardType) need a value-based hashCode consistent with their
    // structural `equals` (see the `Object.equals` override) — an identity hash
    // would violate the equals/hashCode contract for an equal-but-distinct
    // deserialized type (spring-bug-08 SerializableTypeWrapperTests). Hash the
    // canonical `getTypeName()` rendering with FNV-1a (stable, deterministic).
    {
        let cid = ctx.class_id_of_object(this);
        if matches!(
            ctx.class_name_of_id(cid).as_deref(),
            Some("java/lang/reflect/GenericArrayType")
                | Some("java/lang/reflect/ParameterizedType")
                | Some("java/lang/reflect/WildcardType")
        ) {
            let s = crate::phases_late::render_type_name(ctx, &Value::Object(Some(this)));
            let mut h: u32 = 2166136261;
            for b in s.as_bytes() {
                h ^= *b as u32;
                h = h.wrapping_mul(16777619);
            }
            return Ok(Some(Value::Int(h as i32)));
        }
    }
    let hash = ctx.identity_hash_code(this);
    if std::env::var_os("CRATONVM_DBG_VDISP").is_some() {
        eprintln!("[vdisp] native_object_hash_code (IDENTITY) called -> {hash}");
    }
    Ok(Some(Value::Int(hash)))
}

/// Map a synthetic object's stamped class — an interface, an abstract class, or
/// a craton-internal backing class — to the concrete, JDK-plausible class that a
/// real HotSpot JVM reports from `Object.getClass()`.
///
/// Several CratonVM synthetic factories stamp their result with the *interface*
/// or *abstract* type it stands in for (e.g. `IntStream.rangeClosed(..)` →
/// the `java/util/stream/IntStream` interface, `FileSystems.getDefault()` →
/// the abstract `java/nio/file/FileSystem`) or with a private craton-internal
/// name (`List.of(..)` → `cratonvm/internal/UnmodifiableList`). On a real JVM an
/// instance's runtime class is always concrete, so `getClass()` must never
/// surface an interface/abstract/internal type. Native method *dispatch* keys on
/// the resolved declaring class, not the receiver's stamp (see
/// `interpreter.rs`), so re-reporting the class here is decoupled from method
/// resolution — it changes only the Java-visible `Class` mirror, not storage,
/// dispatch, or GC layout.
///
/// Returns the internal (slash-separated) name of the concrete substitute for a
/// stamp whose concrete class is fixed (does not depend on the instance), or
/// `None`. Size-dependent immutable-collection stamps are handled separately by
/// [`immutable_collection_kind`] because their concrete class varies with the
/// element count.
fn jdk_concrete_getclass_alias(stamp: &str) -> Option<&'static str> {
    Some(match stamp {
        // java.util.stream — synthetic streams are stamped with the *interface*.
        // (`IntStream.of(..)` already produces a real `IntPipeline$Head`, so its
        // objects are not stamped with the interface and never reach here.)
        "java/util/stream/Stream" => "java/util/stream/ReferencePipeline$Head",
        "java/util/stream/IntStream" => "java/util/stream/IntPipeline$Head",
        "java/util/stream/LongStream" => "java/util/stream/LongPipeline$Head",
        "java/util/stream/DoubleStream" => "java/util/stream/DoublePipeline$Head",
        // java.net — abstract URLConnection subclasses.
        "java/net/JarURLConnection" => "sun/net/www/protocol/jar/JarURLConnection",
        "java/net/HttpURLConnection" => "sun/net/www/protocol/http/HttpURLConnection",
        // java.nio.file — abstract/interface stamps; the concrete impl is
        // platform specific. Resolution is best-effort: an unavailable class
        // simply falls back to the stamped mirror (see caller).
        "java/nio/file/FileSystem" => {
            if cfg!(windows) {
                "sun/nio/fs/WindowsFileSystem"
            } else {
                "sun/nio/fs/UnixFileSystem"
            }
        }
        "java/nio/file/spi/FileSystemProvider" => {
            if cfg!(windows) {
                "sun/nio/fs/WindowsFileSystemProvider"
            } else {
                "sun/nio/fs/UnixFileSystemProvider"
            }
        }
        "java/nio/file/Path" => {
            if cfg!(windows) {
                "sun/nio/fs/WindowsPath"
            } else {
                "sun/nio/fs/UnixPath"
            }
        }
        _ => return None,
    })
}

/// The resolved display strategy for a stamped class, memoised per stamp.
#[derive(Clone, Copy)]
enum GetClassDisplay {
    /// No remap — report the stamped class unchanged (the common case).
    Stamp,
    /// A fixed concrete alias, already resolved to its `ClassId`.
    Fixed(cratonvm_types::ClassId),
    /// A `cratonvm/internal/Unmodifiable{List,Set,Map}` stamp shared by the
    /// immutable `*.of`/`copyOf` factories and the `Collections.unmodifiable*`
    /// wrappers. Resolved per object: the immutable marker (slot 1) selects the
    /// size-discriminated `ImmutableCollections$*` family (`List12`/`ListN`,
    /// `Set12`/`SetN`, `Map1`/`MapN`); otherwise the `Collections$Unmodifiable*`
    /// family (with a `RandomAccess` check for lists).
    CollList,
    CollSet,
    /// `cratonvm/internal/UnmodifiableSortedSet` ? backs
    /// `Collections.unmodifiableSortedSet` (distinct from `CollSet`, which
    /// backs plain `unmodifiableSet` and does NOT implement SortedSet).
    CollSortedSet,
    /// `cratonvm/internal/UnmodifiableNavigableSet` ? backs
    /// `Collections.unmodifiableNavigableSet` and keeps NavigableSet casts
    /// separate from plain unmodifiable set wrappers.
    CollNavigableSet,
    CollMap,
    /// `cratonvm/internal/UnmodifiableCollection` — only ever produced by
    /// `Collections.unmodifiableCollection` (no immutable factory), so it always
    /// maps to `Collections$UnmodifiableCollection`.
    CollUnmod,
}

/// Classify the craton-internal immutable/unmodifiable collection stamps.
fn collection_display_kind(stamp: &str) -> Option<GetClassDisplay> {
    match stamp {
        "cratonvm/internal/UnmodifiableList" => Some(GetClassDisplay::CollList),
        "cratonvm/internal/UnmodifiableSet" => Some(GetClassDisplay::CollSet),
        // entrySet() view — same display family as a plain UnmodifiableSet
        // (real JDK's `Collections$UnmodifiableMap$UnmodifiableEntrySet` is a
        // distinct inner class, but the existing keySet()/entrySet() display
        // was already unified under CollSet before this class existed).
        "cratonvm/internal/UnmodifiableEntrySet" => Some(GetClassDisplay::CollSet),
        "cratonvm/internal/UnmodifiableSortedSet" => Some(GetClassDisplay::CollSortedSet),
        "cratonvm/internal/UnmodifiableNavigableSet" => Some(GetClassDisplay::CollNavigableSet),
        "cratonvm/internal/UnmodifiableMap" => Some(GetClassDisplay::CollMap),
        "cratonvm/internal/UnmodifiableCollection" => Some(GetClassDisplay::CollUnmod),
        _ => None,
    }
}

thread_local! {
    // Per-stamp memo for the display strategy. `getClass()`/`toString()` are
    // hot; resolving the stamped name (a `String` clone) and loading the alias
    // on every call would allocate each time. `ClassId`s are stable for the VM
    // lifetime, so this never goes stale.
    static GETCLASS_ALIAS_CACHE: std::cell::RefCell<
        std::collections::HashMap<cratonvm_types::ClassId, GetClassDisplay>,
    > = std::cell::RefCell::new(std::collections::HashMap::new());
    // Secondary memo: concrete display name -> resolved `ClassId` (loading on
    // first use). Shared by the fixed and size-dependent paths.
    static GETCLASS_NAME_TO_ID: std::cell::RefCell<
        std::collections::HashMap<&'static str, Option<cratonvm_types::ClassId>>,
    > = std::cell::RefCell::new(std::collections::HashMap::new());
}

/// Resolve (and cache) a concrete display class name to its `ClassId`, loading
/// it on first use. `None` if the class is unavailable (caller falls back).
fn getclass_resolve_name(
    ctx: &mut dyn NativeContext,
    name: &'static str,
) -> Option<cratonvm_types::ClassId> {
    if let Some(cached) = GETCLASS_NAME_TO_ID.with(|c| c.borrow().get(name).copied()) {
        return cached;
    }
    let resolved = ctx.class_id_by_name(name).or_else(|| {
        let _ = ctx.load_class(name);
        ctx.class_id_by_name(name)
    });
    GETCLASS_NAME_TO_ID.with(|c| c.borrow_mut().insert(name, resolved));
    resolved
}

/// The element count of a synthetic immutable collection, via its own `size()`.
/// Best-effort: any failure yields `-1`, which selects the `…N` (multi) form.
fn getclass_collection_size(ctx: &mut dyn NativeContext, this: ObjectRef) -> i64 {
    match ctx.invoke_virtual(this, "size", "()I", &[]) {
        Ok(Some(Value::Int(n))) => n as i64,
        _ => -1,
    }
}

/// Whether a craton-internal collection wrapper was produced by an *immutable*
/// factory (`List.of`/`copyOf` …) rather than `Collections.unmodifiable*`. Reads
/// the marker slot set by `freeze_result` in native-collections. CONTRACT: this
/// index must match `UNMOD_FIELD_IMMUTABLE` (= 1) there.
fn getclass_immutable_marker(ctx: &mut dyn NativeContext, this: ObjectRef) -> bool {
    matches!(ctx.get_field(this, 1), Value::Int(1))
}

/// Whether the backing collection of an unmodifiable-list wrapper implements
/// `java.util.RandomAccess` — HotSpot reports `Collections$UnmodifiableRandom`
/// `AccessList` for those and `Collections$UnmodifiableList` otherwise. The
/// backing lives in slot 0 (`UNMOD_FIELD_BACKING`).
fn getclass_backing_is_random_access(ctx: &mut dyn NativeContext, this: ObjectRef) -> bool {
    let backing = match ctx.get_field(this, 0) {
        Value::Object(Some(b)) => b,
        _ => return false,
    };
    let ra = match getclass_resolve_name(ctx, "java/util/RandomAccess") {
        Some(cid) => cid,
        None => return false,
    };
    let backing_cid = ctx.class_id_of_object(backing);
    ctx.is_subclass(backing_cid, ra)
}

/// Whether the backing set of an unmodifiable-sorted-set wrapper (slot 0,
/// `UNMOD_FIELD_BACKING`) implements `java.util.NavigableSet` — used to pick
/// between `Collections$UnmodifiableSortedSet` and the NavigableSet subclass
/// `Collections$UnmodifiableNavigableSet` for `getClass()` display.
fn getclass_backing_is_navigable_set(ctx: &mut dyn NativeContext, this: ObjectRef) -> bool {
    let backing = match ctx.get_field(this, 0) {
        Value::Object(Some(b)) => b,
        _ => return false,
    };
    let ns = match getclass_resolve_name(ctx, "java/util/NavigableSet") {
        Some(cid) => cid,
        None => return false,
    };
    let backing_cid = ctx.class_id_of_object(backing);
    ctx.is_subclass(backing_cid, ns)
}

/// Resolve the concrete display `ClassId` for an object stamped with `class_id`,
/// or `None` to use the stamp unchanged. The stamp→strategy classification is
/// memoised; the size-dependent collection forms are resolved per-object.
pub(crate) fn getclass_display_class_id(
    ctx: &mut dyn NativeContext,
    class_id: cratonvm_types::ClassId,
    this: ObjectRef,
) -> Option<cratonvm_types::ClassId> {
    let display = match GETCLASS_ALIAS_CACHE.with(|c| c.borrow().get(&class_id).copied()) {
        Some(d) => d,
        None => {
            // Cache miss: classify once. `Stamp` is cached too (negative cache)
            // so the common non-synthetic class never re-clones its name.
            let d = match ctx.class_name_of_id(class_id) {
                Some(name) => {
                    if let Some(kind) = collection_display_kind(&name) {
                        kind
                    } else if let Some(alias) = jdk_concrete_getclass_alias(&name) {
                        match getclass_resolve_name(ctx, alias) {
                            Some(cid) => GetClassDisplay::Fixed(cid),
                            None => GetClassDisplay::Stamp,
                        }
                    } else {
                        GetClassDisplay::Stamp
                    }
                }
                None => GetClassDisplay::Stamp,
            };
            GETCLASS_ALIAS_CACHE.with(|c| c.borrow_mut().insert(class_id, d));
            d
        }
    };
    match display {
        GetClassDisplay::Stamp => None,
        GetClassDisplay::Fixed(cid) => Some(cid),
        // Immutable (marker set): HotSpot picks by size — `List.of()`→ListN,
        // size 1–2→List12, ≥3→ListN; Set mirrors List; Map uses Map1 only for a
        // single entry. Unmodifiable (no marker): the `Collections$Unmodifiable*`
        // family — lists split on `RandomAccess`.
        GetClassDisplay::CollList => {
            let name = if getclass_immutable_marker(ctx, this) {
                let n = getclass_collection_size(ctx, this);
                if (1..=2).contains(&n) {
                    "java/util/ImmutableCollections$List12"
                } else {
                    "java/util/ImmutableCollections$ListN"
                }
            } else if getclass_backing_is_random_access(ctx, this) {
                "java/util/Collections$UnmodifiableRandomAccessList"
            } else {
                "java/util/Collections$UnmodifiableList"
            };
            getclass_resolve_name(ctx, name)
        }
        GetClassDisplay::CollSet => {
            let name = if getclass_immutable_marker(ctx, this) {
                let n = getclass_collection_size(ctx, this);
                if (1..=2).contains(&n) {
                    "java/util/ImmutableCollections$Set12"
                } else {
                    "java/util/ImmutableCollections$SetN"
                }
            } else {
                "java/util/Collections$UnmodifiableSet"
            };
            getclass_resolve_name(ctx, name)
        }
        GetClassDisplay::CollSortedSet => {
            getclass_resolve_name(ctx, "java/util/Collections$UnmodifiableSortedSet")
        }
        GetClassDisplay::CollNavigableSet => {
            getclass_resolve_name(ctx, "java/util/Collections$UnmodifiableNavigableSet")
        }
        GetClassDisplay::CollMap => {
            let name = if getclass_immutable_marker(ctx, this) {
                let n = getclass_collection_size(ctx, this);
                if n == 1 {
                    "java/util/ImmutableCollections$Map1"
                } else {
                    "java/util/ImmutableCollections$MapN"
                }
            } else {
                "java/util/Collections$UnmodifiableMap"
            };
            getclass_resolve_name(ctx, name)
        }
        GetClassDisplay::CollUnmod => {
            getclass_resolve_name(ctx, "java/util/Collections$UnmodifiableCollection")
        }
    }
}

fn native_object_get_class(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(obj))) => *obj,
        _ => {
            return Err(cratonvm_types::error::RuntimeError::NullPointerException {
                message: Some("getClass on null".to_string()),
            }
            .into());
        }
    };

    if std::env::var("CRATONVM_DBG_TOARRAY").is_ok() {
        eprintln!(
            "[DBG_TOARRAY] native_object_get_class ENTER kind={:?} cid={:?} len={}",
            ctx.heap_kind_of(this),
            ctx.class_id_of_object(this),
            if ctx.heap_kind_of(this) == cratonvm_types::ObjectKind::Array {
                ctx.array_length(this) as i64
            } else {
                -1
            }
        );
    }
    // For array objects, build a class mirror with the correct array type name
    // (e.g., "[I" for int[], "[Ljava/lang/String;" for String[]).
    // Primitive arrays use ClassId(0) + element_type; reference arrays store
    // the component ClassId in the header.
    if ctx.heap_kind_of(this) == cratonvm_types::ObjectKind::Array {
        let class_id = ctx.class_id_of_object(this);
        let element_type = ctx.heap_element_type_of(this);
        // Primitive-array type-name constants — `&'static str` so the eight
        // common branches do not allocate at all (the previous code called
        // `.to_string()` on each, adding a per-call heap alloc on every
        // `Object.getClass()` against a primitive array).
        const ARRAY_BOOLEAN: &str = "[Z";
        const ARRAY_CHAR: &str = "[C";
        const ARRAY_FLOAT: &str = "[F";
        const ARRAY_DOUBLE: &str = "[D";
        const ARRAY_BYTE: &str = "[B";
        const ARRAY_SHORT: &str = "[S";
        const ARRAY_INT: &str = "[I";
        const ARRAY_LONG: &str = "[J";
        // For primitive arrays we hold a `&'static str`; for reference
        // arrays we synthesise the array descriptor (one alloc, unavoidable
        // because the component class name is dynamic). `Cow` lets us pass
        // either uniformly to `class_id_by_name` / `load_class` /
        // `primitive_class_mirror` without an extra copy.
        let array_class_name: std::borrow::Cow<'static, str> = match element_type {
            cratonvm_types::ArrayElementType::Boolean => std::borrow::Cow::Borrowed(ARRAY_BOOLEAN),
            cratonvm_types::ArrayElementType::Char => std::borrow::Cow::Borrowed(ARRAY_CHAR),
            cratonvm_types::ArrayElementType::Float => std::borrow::Cow::Borrowed(ARRAY_FLOAT),
            cratonvm_types::ArrayElementType::Double => std::borrow::Cow::Borrowed(ARRAY_DOUBLE),
            cratonvm_types::ArrayElementType::Byte => std::borrow::Cow::Borrowed(ARRAY_BYTE),
            cratonvm_types::ArrayElementType::Short => std::borrow::Cow::Borrowed(ARRAY_SHORT),
            cratonvm_types::ArrayElementType::Int => std::borrow::Cow::Borrowed(ARRAY_INT),
            cratonvm_types::ArrayElementType::Long => std::borrow::Cow::Borrowed(ARRAY_LONG),
            cratonvm_types::ArrayElementType::Reference => {
                // Component class_id is stored in the array header
                let comp_name = ctx
                    .class_name_of_id(class_id)
                    .unwrap_or_else(|| "java/lang/Object".to_string());
                if comp_name.starts_with('[') {
                    // Multi-dimensional array: prepend another '['
                    std::borrow::Cow::Owned(format!("[{comp_name}"))
                } else {
                    std::borrow::Cow::Owned(format!("[L{comp_name};"))
                }
            }
        };
        // Create a class mirror with the array type name.  We need a real
        // (non-primitive) class mirror so that `Class.isPrimitive()` returns
        // false and the identity matches the `Foo[].class` literal — both
        // are required by Spring's `ClassUtils.resolvePrimitiveIfNecessary`
        // (called via `TypeDescriptor.getObjectType`) which otherwise reads
        // `isPrimitive()==true` for an `Object[]` mirror produced here and
        // returns `null`, surfacing as `NPE: Cannot invoke isInstance on
        // null` inside `GenericConversionService.convert`.
        if std::env::var("CRATONVM_DBG_TOARRAY").is_ok() {
            eprintln!(
                "[DBG_TOARRAY] getClass array_class_name={:?} comp_cid={:?} arr_len={}",
                array_class_name,
                class_id,
                ctx.array_length(this)
            );
        }
        if let Some(arr_cid) = ctx.class_id_by_name(&array_class_name) {
            let mirror = ctx.get_class_mirror(arr_cid);
            return Ok(Some(Value::Object(Some(mirror))));
        }
        let _ = ctx.load_class(&array_class_name);
        if let Some(arr_cid) = ctx.class_id_by_name(&array_class_name) {
            let mirror = ctx.get_class_mirror(arr_cid);
            return Ok(Some(Value::Object(Some(mirror))));
        }
        // Last-resort fallback (e.g. degenerate names that fail to synthesise):
        // keep the old behaviour so we never return a null mirror.
        let mirror = ctx.primitive_class_mirror(&array_class_name);
        return Ok(Some(Value::Object(Some(mirror))));
    }

    let class_id = ctx.class_id_of_object(this);
    // Synthetic objects are sometimes stamped with the interface/abstract/
    // internal type they stand in for; a real JVM always reports a concrete
    // runtime class. Re-map to a JDK-plausible concrete class for the mirror
    // (memoised; no-op for ordinary classes). Storage/dispatch are unaffected.
    let display_id = getclass_display_class_id(ctx, class_id, this).unwrap_or(class_id);
    let mirror = ctx.get_class_mirror(display_id);
    Ok(Some(Value::Object(Some(mirror))))
}

// ---------------------------------------------------------------------------
// `Object.toString` per-class dotted-name cache (perf)
//
// `Object.toString` is one of the hottest natives in the VM (every implicit
// string concatenation against a non-overriding class hits it). The naive
// implementation allocated four times per call: `class_name_of_id`, the
// `replace('/', ".")` of the slashed name, the `format!` of the
// `"dotted@hash"` text, and finally `create_string`.
//
// We mirror the cache strategy in `lang_class.rs::dotted_class_name`: the
// slashed → dotted derivation is pure (class names don't change once the
// class is loaded), so we memoise the `Arc<str>` keyed by `ClassId`. After
// the first call per class only one allocation remains (the `format!` for
// the per-object `dotted@hash` text — unavoidable because the hash varies).
// ---------------------------------------------------------------------------
fn object_to_string_dotted_name(
    ctx: &mut dyn NativeContext,
    class_id: ClassId,
) -> std::sync::Arc<str> {
    use parking_lot::RwLock;
    use rustc_hash::FxHashMap;
    use std::sync::{Arc, OnceLock};

    static CACHE: OnceLock<RwLock<FxHashMap<u32, Arc<str>>>> = OnceLock::new();
    let cache = CACHE.get_or_init(|| RwLock::new(FxHashMap::default()));
    let key = class_id.as_u32();
    if let Some(arc) = cache.read().get(&key).cloned() {
        return arc;
    }
    // Miss: derive the dotted form (single `replace` or `Arc::from` clone if
    // the name has no `/`) and insert under the write lock.
    let slashed = ctx
        .class_name_of_id(class_id)
        .unwrap_or_else(|| "?".to_string());
    let dotted: Arc<str> = if slashed.contains('/') {
        Arc::from(slashed.replace('/', "."))
    } else {
        Arc::from(slashed)
    };
    cache.write().insert(key, Arc::clone(&dotted));
    dotted
}

fn native_object_to_string(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    use std::fmt::Write as _;
    let this = match args.first() {
        Some(Value::Object(Some(obj))) => *obj,
        _ => {
            return Err(cratonvm_types::error::RuntimeError::NullPointerException {
                message: Some("toString on null".to_string()),
            }
            .into());
        }
    };
    let class_id = ctx.class_id_of_object(this);
    if ctx.class_name_of_id(class_id).as_deref() == Some("org/apache/tomcat/util/buf/MessageBytes")
    {
        return native_message_bytes_to_string(ctx, args);
    }
    // Keep the default `toString` class name consistent with `getClass()`:
    // synthetic objects stamped with an interface/abstract/internal class
    // report their concrete JDK display class here too (memoised; no-op for
    // ordinary classes).
    let class_id = getclass_display_class_id(ctx, class_id, this).unwrap_or(class_id);
    let dotted = object_to_string_dotted_name(ctx, class_id);
    // JDK `Object.toString` renders `Integer.toHexString(hashCode())`, a VIRTUAL
    // call — a bytecode `hashCode()` override must show through here (see the twin
    // fix in the `Object.toString` registration near the top of this file for the
    // CGLIB proxy-cache rationale). Non-overriding receivers dispatch to the
    // identity native, so their rendering is unchanged.
    let hash = match ctx.invoke_virtual(this, "hashCode", "()I", &[]) {
        Ok(Some(Value::Int(h))) => h,
        _ => ctx.identity_hash_code(this),
    };
    // Build "dotted@hash" with a single pre-sized buffer (saves the realloc
    // that `format!` would do, but more importantly limits us to one heap
    // alloc for this call — the per-object hash means we cannot cache this).
    // `hash` is i32 → up to 8 hex chars; plus '@' separator.
    let mut text = String::with_capacity(dotted.len() + 9);
    text.push_str(&dotted);
    let _ = write!(text, "@{hash:x}");
    let str_ref = ctx.create_string(&text);
    Ok(Some(Value::Object(Some(str_ref))))
}

fn native_object_equals(_ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    // Default equals: reference identity
    let this = args.first().copied().unwrap_or(Value::Object(None));
    let other = args.get(1).copied().unwrap_or(Value::Object(None));
    let equal = match (this, other) {
        (Value::Object(Some(a)), Value::Object(Some(b))) => a.as_ptr() == b.as_ptr(),
        (Value::Object(None), Value::Object(None)) => true,
        _ => false,
    };
    if std::env::var_os("CRATONVM_DBG_OBJ_EQUALS").is_some() {
        let aid = match this {
            Value::Object(Some(o)) => o.as_ptr() as usize,
            _ => 0,
        };
        let bid = match other {
            Value::Object(Some(o)) => o.as_ptr() as usize,
            _ => 0,
        };
        eprintln!("[obj-eq] a={aid:x} b={bid:x} -> {equal}");
    }
    Ok(Some(Value::Int(if equal { 1 } else { 0 })))
}

fn native_object_clone(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(obj))) => *obj,
        _ => {
            return Err(cratonvm_types::error::RuntimeError::NullPointerException {
                message: Some("clone on null".to_string()),
            }
            .into());
        }
    };
    let class_id = ctx.class_id_of_object(this);
    let kind = ctx.heap_kind_of(this);
    if std::env::var_os("CRATONVM_DBG_CLONE").is_some() {
        let name = ctx
            .class_name_of_id(class_id)
            .unwrap_or_else(|| "<unknown>".to_string());
        eprintln!("[DBG_CLONE] kind={:?} class={}", kind, name);
    }
    match kind {
        cratonvm_types::ObjectKind::Object => {
            let num_fields = ctx.object_num_fields(this);
            let clone_ref = ctx.alloc_object(class_id, num_fields);
            for i in 0..num_fields {
                let val = ctx.get_field(this, i);
                ctx.set_field(clone_ref, i, val);
            }
            // KC26 LinkedHashMap.clone fix: LHM (and subclasses like
            // AnnotationAttributes) keeps most of its state in a side-table
            // overlay keyed by the receiver's identity hash code (C21:
            // GC-stable across moving collections), not in the heap fields
            // the loop above copies. Without this, the cloned LHM has all
            // state missing (size, table, head/tail) and a subsequent
            // `HashMap.clone()` → `reinitialize()` → `putMapEntries()` chain
            // walks an empty receiver, producing OOM via division-by-zero
            // load-factor or silent data loss.  Detect LHM ancestry on the
            // receiver and replicate the overlay onto the clone.
            let mut cur = class_id;
            loop {
                match ctx.class_name_of_id(cur) {
                    Some(n) if n == "java/util/LinkedHashMap" => {
                        cratonvm_native_collections::clone_lhm_overlay(this, clone_ref);
                        break;
                    }
                    // TC0622: `Properties` keeps its entries in an identity-keyed
                    // side-table (`properties_sidetable`), NOT the heap fields the
                    // shallow loop above copies. A fresh clone has a new identity
                    // and therefore an empty side-table, so `getProperty` /
                    // `propertyNames` / `stringPropertyNames` would see nothing
                    // (the inherited Hashtable `defaults` field IS copied above, so
                    // the defaults fallback still works). Snapshot the receiver's
                    // side-table onto the clone — same pattern as the LinkedHashMap
                    // overlay just above. This is what makes
                    // `(Properties) props.clone()` round-trip its keys, e.g. the
                    // env Hashtable JNDI clones in `InitialContext.<init>` and any
                    // app that clones a Properties.
                    Some(n) if n == "java/util/Properties" => {
                        let snap = crate::properties_sidetable::snapshot_sidetable(ctx, this);
                        if !snap.is_empty() {
                            crate::properties_sidetable::replace_sidetable(ctx, clone_ref, &snap);
                        }
                        break;
                    }
                    Some(n) if n == "java/lang/Object" => break,
                    None => break,
                    _ => match ctx.superclass_of(cur) {
                        Some(p) => cur = p,
                        None => break,
                    },
                }
            }
            Ok(Some(Value::Object(Some(clone_ref))))
        }
        cratonvm_types::ObjectKind::Array => {
            let len = ctx.array_length(this);
            let et = ctx.heap_element_type_of(this);
            let clone = if et == cratonvm_types::ArrayElementType::Reference {
                ctx.new_ref_array(class_id, len)
            } else {
                ctx.new_array(et, len)
            };
            for i in 0..len {
                let val = ctx.get_array_element(this, i);
                ctx.set_array_element(clone, i, val);
            }
            Ok(Some(Value::Object(Some(clone))))
        }
        // Round-9 gc CRIT-1: HumongousFiller is a GC-internal walker
        // sentinel that should never reach the Object.clone() path.
        // If it ever does, treat it as an NPE rather than silently
        // returning a clone of garbage.
        cratonvm_types::ObjectKind::HumongousFiller => {
            Err(cratonvm_types::error::RuntimeError::NullPointerException {
                message: Some("clone on humongous-continuation filler (GC sentinel)".to_string()),
            }
            .into())
        }
    }
}

/// No-op native that accepts `this` but does nothing.
// ---------------------------------------------------------------------------
// System.in/out/err override storage (used by setIn0/setOut0/setErr0)
// ---------------------------------------------------------------------------

/// Process-wide table of System stream overrides set via System.setIn/setOut/setErr.
/// Keyed by "in" / "out" / "err". Stores the most recently installed stream reference.
fn system_overridden_streams(
) -> &'static parking_lot::Mutex<std::collections::HashMap<&'static str, ObjectRef>> {
    use std::sync::OnceLock;
    static OVERRIDES: OnceLock<
        parking_lot::Mutex<std::collections::HashMap<&'static str, ObjectRef>>,
    > = OnceLock::new();
    OVERRIDES.get_or_init(|| parking_lot::Mutex::new(std::collections::HashMap::new()))
}

/// Set the override for the given stream name ("in", "out", or "err").
pub(crate) fn system_set_overridden_stream(name: &'static str, stream: ObjectRef) {
    system_overridden_streams().lock().insert(name, stream);
}

/// Remove the override for the given stream name (back to default).
pub(crate) fn system_clear_overridden_stream(name: &'static str) {
    system_overridden_streams().lock().remove(name);
}

/// Read the current override for the given stream name ("in"/"out"/"err"),
/// if one was installed via `System.setIn/setOut/setErr` (→ `setIn0`/`setOut0`/
/// `setErr0`). The interpreter's `getstatic System.out/err` bootstrap intercept
/// consults this so a user redirect is honored instead of always returning the
/// canonical synthetic fd-backed stream.
pub fn system_overridden_stream(name: &str) -> Option<ObjectRef> {
    system_overridden_streams().lock().get(name).copied()
}

/// Process-wide default Locale set via Locale.setDefault.
fn locale_default() -> &'static parking_lot::Mutex<Option<ObjectRef>> {
    use std::sync::OnceLock;
    static DEFAULT: OnceLock<parking_lot::Mutex<Option<ObjectRef>>> = OnceLock::new();
    DEFAULT.get_or_init(|| parking_lot::Mutex::new(None))
}

/// Side-table mapping a CratonVM-synthesised `java/util/Locale` ObjectRef to
/// its `(language, country, variant)` strings.
///
/// CRITICAL: `java.util.Locale` is a real bootstrap class whose instance
/// fields are `baseLocale` (a `sun.util.locale.BaseLocale`) and
/// `localeExtensions` (a `sun.util.locale.LocaleExtensions`) — NOT plain
/// `String` language/country/variant fields. Earlier code wrote the
/// language/country Strings straight into instance slots 0/1/2. When a
/// real-JDK `Locale` method that we do NOT natively override runs against
/// such an object (e.g. `getUnicodeLocaleType`), its bytecode does
/// `getfield localeExtensions; invokevirtual LocaleExtensions.getXxx()` —
/// but slot 1 holds a `String`, so the `invokevirtual` retargets onto
/// `java/lang/String` and raises a bogus
/// `NoSuchMethodError java/lang/String.getUnicodeLocaleType(...)`.
///
/// To avoid poisoning the real-JDK field layout, the synthetic Locale's
/// instance slots are left untouched (null / zero-initialised, which is the
/// spec-correct "no extensions" shape). The language/country/variant data
/// lives here instead, keyed by ObjectRef, and every Locale accessor native
/// reads from this table.
fn locale_data(
) -> &'static parking_lot::Mutex<std::collections::HashMap<ObjectRef, (String, String, String)>> {
    use std::sync::OnceLock;
    static DATA: OnceLock<
        parking_lot::Mutex<std::collections::HashMap<ObjectRef, (String, String, String)>>,
    > = OnceLock::new();
    DATA.get_or_init(|| parking_lot::Mutex::new(std::collections::HashMap::new()))
}

/// Record a synthetic Locale's `(language, country, variant)` in the side
/// table. See [`locale_data`] for why instance fields must not be used.
pub(crate) fn locale_data_set(obj: ObjectRef, lang: &str, country: &str, variant: &str) {
    locale_data().lock().insert(
        obj,
        (lang.to_string(), country.to_string(), variant.to_string()),
    );
}

/// Read a synthetic Locale's `(language, country, variant)` from the side
/// table. Returns empty strings for a Locale we never recorded (e.g. a
/// real-JDK-constructed Locale) — callers treat that as the root locale.
pub(crate) fn locale_data_get(obj: ObjectRef) -> (String, String, String) {
    locale_data().lock().get(&obj).cloned().unwrap_or_default()
}

/// GC root scan for all process-global Locale caches (this module's
/// `locale_default` + `locale_data`, plus the `locale_bootstrap` caches). These
/// hold live synthetic `java/util/Locale` objects reachable only from Rust-side
/// mutexes; without rooting+remapping they go stale after a moving young GC and
/// a later `Locale` method dispatch SIGSEGVs ("Stale pointer … java/util/Locale").
pub fn gc_scan_locale_roots(out: &mut Vec<ObjectRef>) {
    if let Some(o) = *locale_default().lock() {
        out.push(o);
    }
    for k in locale_data().lock().keys() {
        out.push(*k);
    }
    crate::locale_bootstrap::gc_scan_locale_roots(out);
}

/// Post-GC remap companion to [`gc_scan_locale_roots`].
pub fn gc_update_locale_refs(pointer_map: &std::collections::HashMap<usize, usize>) {
    if pointer_map.is_empty() {
        return;
    }
    {
        let mut slot = locale_default().lock();
        if let Some(obj) = slot.as_mut() {
            if let Some(&new_addr) = pointer_map.get(&(obj.as_ptr() as usize)) {
                *obj = unsafe { ObjectRef::from_raw(new_addr as *mut u8) };
            }
        }
    }
    {
        let mut map = locale_data().lock();
        let drained: Vec<_> = map.drain().collect();
        for (k, v) in drained {
            let nk = pointer_map
                .get(&(k.as_ptr() as usize))
                .map(|&n| unsafe { ObjectRef::from_raw(n as *mut u8) })
                .unwrap_or(k);
            map.insert(nk, v);
        }
    }
    crate::locale_bootstrap::gc_update_locale_refs(pointer_map);
}

pub(crate) fn native_noop_with_this(
    _ctx: &mut dyn NativeContext,
    _args: &[Value],
) -> MethodCallResult {
    Ok(None)
}

// ---------------------------------------------------------------------------
// Object.wait / notify / notifyAll
// ---------------------------------------------------------------------------

fn native_object_wait(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(obj))) => *obj,
        _ => return Ok(None),
    };
    ctx.monitor_wait(this, None)
}

fn native_object_wait_timeout(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(obj))) => *obj,
        _ => return Ok(None),
    };
    let timeout_ms = match args.get(1) {
        Some(Value::Long(ms)) => {
            if *ms > 0 {
                Some(*ms as u64)
            } else {
                None
            }
        }
        _ => None,
    };
    ctx.monitor_wait(this, timeout_ms)
}

/// T2.2.2: `Object.wait(long millis, int nanos)` — per `Object.wait(J)`V
/// semantics in JLS §17.2, the nanos parameter rounds the timeout up by
/// one millisecond if any of the nanos are non-zero (sub-millisecond
/// resolution is not guaranteed and HotSpot rounds the same way).
///
/// Validates argument ranges per the JDK spec:
///   * `millis < 0` → IllegalArgumentException
///   * `nanos` outside `[0, 999_999]` → IllegalArgumentException
///
/// Delegates to [`ctx.monitor_wait`] with the effective millisecond
/// timeout.
fn native_object_wait_timeout_nanos(
    ctx: &mut dyn NativeContext,
    args: &[Value],
) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(obj))) => *obj,
        _ => return Ok(None),
    };
    let millis = match args.get(1) {
        Some(Value::Long(v)) => *v,
        _ => 0,
    };
    let nanos = match args.get(2) {
        Some(Value::Int(v)) => *v,
        _ => 0,
    };
    if millis < 0 {
        return Err(
            cratonvm_types::error::RuntimeError::IllegalArgumentException {
                message: "Object.wait: timeout value is negative".to_string(),
            }
            .into(),
        );
    }
    if !(0..=999_999).contains(&nanos) {
        return Err(
            cratonvm_types::error::RuntimeError::IllegalArgumentException {
                message: "Object.wait: nanosecond timeout value out of range".to_string(),
            }
            .into(),
        );
    }
    // HotSpot rounds sub-millisecond nanos up to one extra millisecond so
    // the caller never gets back *before* its requested interval.
    let effective_ms = if nanos > 0 {
        millis.saturating_add(1)
    } else {
        millis
    };
    let timeout_ms = if effective_ms > 0 {
        Some(effective_ms as u64)
    } else {
        None
    };
    ctx.monitor_wait(this, timeout_ms)
}

fn native_object_notify(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(obj))) => *obj,
        _ => return Ok(None),
    };
    ctx.monitor_notify(this)
}

fn native_object_notify_all(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(obj))) => *obj,
        _ => return Ok(None),
    };
    ctx.monitor_notify_all(this)
}

