pub(crate) fn real_sha512(data: &[u8]) -> Vec<u8> {
    let mut h: [u64; 8] = [
        0x6a09e667f3bcc908,
        0xbb67ae8584caa73b,
        0x3c6ef372fe94f82b,
        0xa54ff53a5f1d36f1,
        0x510e527fade682d1,
        0x9b05688c2b3e6c1f,
        0x1f83d9abfb41bd6b,
        0x5be0cd19137e2179,
    ];

    // Pre-processing: pad message to 1024-bit blocks
    let bit_len = (data.len() as u128).wrapping_mul(8);
    let mut msg = data.to_vec();
    msg.push(0x80);
    while msg.len() % 128 != 112 {
        msg.push(0x00);
    }
    msg.extend_from_slice(&bit_len.to_be_bytes());

    // Process each 1024-bit (128-byte) block
    for chunk in msg.chunks_exact(128) {
        let mut w = [0u64; 80];
        for i in 0..16 {
            w[i] = u64::from_be_bytes([
                chunk[8 * i],
                chunk[8 * i + 1],
                chunk[8 * i + 2],
                chunk[8 * i + 3],
                chunk[8 * i + 4],
                chunk[8 * i + 5],
                chunk[8 * i + 6],
                chunk[8 * i + 7],
            ]);
        }
        for i in 16..80 {
            let s0 = w[i - 15].rotate_right(1) ^ w[i - 15].rotate_right(8) ^ (w[i - 15] >> 7);
            let s1 = w[i - 2].rotate_right(19) ^ w[i - 2].rotate_right(61) ^ (w[i - 2] >> 6);
            w[i] = w[i - 16]
                .wrapping_add(s0)
                .wrapping_add(w[i - 7])
                .wrapping_add(s1);
        }

        let mut a = h[0];
        let mut b = h[1];
        let mut c = h[2];
        let mut d = h[3];
        let mut e = h[4];
        let mut f = h[5];
        let mut g = h[6];
        let mut hh = h[7];

        for i in 0..80 {
            let s1 = e.rotate_right(14) ^ e.rotate_right(18) ^ e.rotate_right(41);
            let ch = (e & f) ^ ((!e) & g);
            let temp1 = hh
                .wrapping_add(s1)
                .wrapping_add(ch)
                .wrapping_add(SHA512_K[i])
                .wrapping_add(w[i]);
            let s0 = a.rotate_right(28) ^ a.rotate_right(34) ^ a.rotate_right(39);
            let maj = (a & b) ^ (a & c) ^ (b & c);
            let temp2 = s0.wrapping_add(maj);

            hh = g;
            g = f;
            f = e;
            e = d.wrapping_add(temp1);
            d = c;
            c = b;
            b = a;
            a = temp1.wrapping_add(temp2);
        }

        h[0] = h[0].wrapping_add(a);
        h[1] = h[1].wrapping_add(b);
        h[2] = h[2].wrapping_add(c);
        h[3] = h[3].wrapping_add(d);
        h[4] = h[4].wrapping_add(e);
        h[5] = h[5].wrapping_add(f);
        h[6] = h[6].wrapping_add(g);
        h[7] = h[7].wrapping_add(hh);
    }

    let mut result = Vec::with_capacity(64);
    for word in &h {
        result.extend_from_slice(&word.to_be_bytes());
    }
    result
}

/// SHA-384 is SHA-512 with different initial values, truncated to 384 bits (48 bytes).
pub(crate) fn real_sha384(data: &[u8]) -> Vec<u8> {
    let mut h: [u64; 8] = [
        0xcbbb9d5dc1059ed8,
        0x629a292a367cd507,
        0x9159015a3070dd17,
        0x152fecd8f70e5939,
        0x67332667ffc00b31,
        0x8eb44a8768581511,
        0xdb0c2e0d64f98fa7,
        0x47b5481dbefa4fa4,
    ];

    // Same padding as SHA-512: 1024-bit blocks
    let bit_len = (data.len() as u128).wrapping_mul(8);
    let mut msg = data.to_vec();
    msg.push(0x80);
    while msg.len() % 128 != 112 {
        msg.push(0x00);
    }
    msg.extend_from_slice(&bit_len.to_be_bytes());

    for chunk in msg.chunks_exact(128) {
        let mut w = [0u64; 80];
        for i in 0..16 {
            w[i] = u64::from_be_bytes([
                chunk[8 * i],
                chunk[8 * i + 1],
                chunk[8 * i + 2],
                chunk[8 * i + 3],
                chunk[8 * i + 4],
                chunk[8 * i + 5],
                chunk[8 * i + 6],
                chunk[8 * i + 7],
            ]);
        }
        for i in 16..80 {
            let s0 = w[i - 15].rotate_right(1) ^ w[i - 15].rotate_right(8) ^ (w[i - 15] >> 7);
            let s1 = w[i - 2].rotate_right(19) ^ w[i - 2].rotate_right(61) ^ (w[i - 2] >> 6);
            w[i] = w[i - 16]
                .wrapping_add(s0)
                .wrapping_add(w[i - 7])
                .wrapping_add(s1);
        }

        let mut a = h[0];
        let mut b = h[1];
        let mut c = h[2];
        let mut d = h[3];
        let mut e = h[4];
        let mut f = h[5];
        let mut g = h[6];
        let mut hh = h[7];

        for i in 0..80 {
            let s1 = e.rotate_right(14) ^ e.rotate_right(18) ^ e.rotate_right(41);
            let ch = (e & f) ^ ((!e) & g);
            let temp1 = hh
                .wrapping_add(s1)
                .wrapping_add(ch)
                .wrapping_add(SHA512_K[i])
                .wrapping_add(w[i]);
            let s0 = a.rotate_right(28) ^ a.rotate_right(34) ^ a.rotate_right(39);
            let maj = (a & b) ^ (a & c) ^ (b & c);
            let temp2 = s0.wrapping_add(maj);

            hh = g;
            g = f;
            f = e;
            e = d.wrapping_add(temp1);
            d = c;
            c = b;
            b = a;
            a = temp1.wrapping_add(temp2);
        }

        h[0] = h[0].wrapping_add(a);
        h[1] = h[1].wrapping_add(b);
        h[2] = h[2].wrapping_add(c);
        h[3] = h[3].wrapping_add(d);
        h[4] = h[4].wrapping_add(e);
        h[5] = h[5].wrapping_add(f);
        h[6] = h[6].wrapping_add(g);
        h[7] = h[7].wrapping_add(hh);
    }

    // Truncate to 384 bits (6 words = 48 bytes)
    let mut result = Vec::with_capacity(48);
    for word in &h[..6] {
        result.extend_from_slice(&word.to_be_bytes());
    }
    result
}

// ===========================================================================
// Generic HMAC construction (RFC 2104)
// ===========================================================================

/// Generic HMAC: HMAC(K, data) = H((K' ⊕ opad) || H((K' ⊕ ipad) || data))
/// `hash_fn` is the underlying hash, `block_size` is the hash's internal block size.
fn hmac_generic(
    key: &[u8],
    data: &[u8],
    hash_fn: fn(&[u8]) -> Vec<u8>,
    block_size: usize,
) -> Vec<u8> {
    // Step 1: If key > block size, hash it; if shorter, pad with zeros
    let mut key_block = vec![0u8; block_size];
    if key.len() > block_size {
        let hashed = hash_fn(key);
        key_block[..hashed.len()].copy_from_slice(&hashed);
    } else {
        key_block[..key.len()].copy_from_slice(key);
    }

    // Step 2: Create inner and outer padded keys
    let mut i_key_pad = vec![0u8; block_size];
    let mut o_key_pad = vec![0u8; block_size];
    for i in 0..block_size {
        i_key_pad[i] = key_block[i] ^ 0x36;
        o_key_pad[i] = key_block[i] ^ 0x5c;
    }

    // Step 3: inner hash = H(i_key_pad || data)
    let mut inner_msg = Vec::with_capacity(block_size + data.len());
    inner_msg.extend_from_slice(&i_key_pad);
    inner_msg.extend_from_slice(data);
    let inner_hash = hash_fn(&inner_msg);

    // Step 4: outer hash = H(o_key_pad || inner_hash)
    let mut outer_msg = Vec::with_capacity(block_size + inner_hash.len());
    outer_msg.extend_from_slice(&o_key_pad);
    outer_msg.extend_from_slice(&inner_hash);
    hash_fn(&outer_msg)
}

/// HMAC-SHA-384 (128-byte block size, same as SHA-512)
pub(crate) fn hmac_sha384(key: &[u8], data: &[u8]) -> Vec<u8> {
    hmac_generic(key, data, real_sha384, 128)
}

/// HMAC-SHA-512 (128-byte block size)
pub(crate) fn hmac_sha512(key: &[u8], data: &[u8]) -> Vec<u8> {
    hmac_generic(key, data, real_sha512, 128)
}

/// HMAC-SHA-1 (64-byte block size)
pub(crate) fn hmac_sha1(key: &[u8], data: &[u8]) -> Vec<u8> {
    hmac_generic(key, data, real_sha1, 64)
}

/// HMAC-MD5 (64-byte block size)
pub(crate) fn hmac_md5(key: &[u8], data: &[u8]) -> Vec<u8> {
    hmac_generic(key, data, real_md5, 64)
}

fn native_md_digest(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Object(None))),
    };
    let algo = match ctx.get_field(this, MD_FIELD_ALGO) {
        Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
        _ => String::new(),
    };
    let data_arr = match ctx.get_field(this, MD_FIELD_DATA) {
        Value::Object(Some(o)) => o,
        _ => return Ok(Some(Value::Object(None))),
    };
    let len = ctx.array_length(data_arr);
    let mut data = Vec::with_capacity(len);
    for i in 0..len {
        if let Value::Int(b) = ctx.get_array_element(data_arr, i) {
            data.push(b as u8);
        }
    }
    let digest = compute_digest(&algo, &data);
    // GC-safety: `this` is a bare Rust local (from `args.first()`) held
    // across two further allocating calls below (`new_array` x2). Either
    // can trigger a moving GC that relocates `this`; the final "reset"
    // `set_field` must re-read through a pin or it silently lands on an
    // abandoned from-space copy, leaving the live instance's accumulator
    // un-reset -- same unread-pin anti-pattern fixed in
    // `populate_real_thread_holder` (GCBARRIER-CDLWAIT-FIX, 2026-07-17).
    let this_handle = ctx.pin_native_root(this);
    let result = ctx.new_array(cratonvm_types::ArrayElementType::Byte, digest.len());
    let result_handle = ctx.pin_native_root(result);
    for (i, &b) in digest.iter().enumerate() {
        ctx.set_array_element(result, i, Value::Int(b as i8 as i32));
    }
    // Reset
    let empty = ctx.new_array(cratonvm_types::ArrayElementType::Byte, 0);
    let this = ctx.read_native_pin(this_handle, this);
    let result = ctx.read_native_pin(result_handle, result);
    ctx.set_field(this, MD_FIELD_DATA, Value::Object(Some(empty)));
    ctx.unpin_native_roots(this_handle);
    Ok(Some(Value::Object(Some(result))))
}

fn native_md_digest_input(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Object(None))),
    };
    // update with input first
    if let Some(Value::Object(Some(arr))) = args.get(1) {
        let len = ctx.array_length(*arr);
        let mut bytes = Vec::with_capacity(len);
        for i in 0..len {
            if let Value::Int(b) = ctx.get_array_element(*arr, i) {
                bytes.push(b as u8);
            }
        }
        md_append_bytes(ctx, this, &bytes);
    }
    native_md_digest(ctx, args)
}

/// `int MessageDigest.digest(byte[] buf, int offset, int len)` — completes the
/// digest into the caller's buffer and returns the number of bytes written.
/// Without this native the call ran the real JDK bytecode, which dispatches to
/// the abstract `MessageDigestSpi.engineDigest()` (no Code attribute) and threw
/// `AbstractMethodError` — e.g. Kafka's `SkimpyOffsetMap.hashInto` uses this
/// overload (OffsetMapTest), not the `digest()[B` form the other natives cover.
fn native_md_digest_buf(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Int(0))),
    };
    let buf = match args.get(1) {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Int(0))),
    };
    let offset = match args.get(2) {
        Some(Value::Int(v)) => (*v).max(0) as usize,
        _ => 0,
    };
    let len = match args.get(3) {
        Some(Value::Int(v)) => (*v).max(0) as usize,
        _ => 0,
    };
    let algo = match ctx.get_field(this, MD_FIELD_ALGO) {
        Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
        _ => String::new(),
    };
    let data = match ctx.get_field(this, MD_FIELD_DATA) {
        Value::Object(Some(arr)) => {
            let n = ctx.array_length(arr);
            let mut v = Vec::with_capacity(n);
            for i in 0..n {
                if let Value::Int(b) = ctx.get_array_element(arr, i) {
                    v.push(b as u8);
                }
            }
            v
        }
        _ => Vec::new(),
    };
    let digest = compute_digest(&algo, &data);
    // JDK writes the full digest (callers size `len` to the digest length); we
    // additionally clamp to both `len` and the array bounds to fail safe.
    let cap = ctx.array_length(buf);
    let n = digest.len().min(len).min(cap.saturating_sub(offset));
    for i in 0..n {
        ctx.set_array_element(buf, offset + i, Value::Int(digest[i] as i8 as i32));
    }
    // Reset the running state, matching `digest()`'s post-finalization reset.
    let empty = ctx.new_array(cratonvm_types::ArrayElementType::Byte, 0);
    ctx.set_field(this, MD_FIELD_DATA, Value::Object(Some(empty)));
    Ok(Some(Value::Int(digest.len() as i32)))
}

fn native_md_reset(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(None),
    };
    let empty = ctx.new_array(cratonvm_types::ArrayElementType::Byte, 0);
    ctx.set_field(this, MD_FIELD_DATA, Value::Object(Some(empty)));
    Ok(None)
}

fn native_md_get_algorithm(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Object(None))),
    };
    Ok(Some(ctx.get_field(this, MD_FIELD_ALGO)))
}

fn native_md_get_digest_length(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Int(0))),
    };
    let algo = match ctx.get_field(this, MD_FIELD_ALGO) {
        Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
        _ => String::new(),
    };
    let len = match algo.to_uppercase().replace('-', "").as_str() {
        "MD5" => 16,
        "SHA1" | "SHA" => 20,
        "SHA256" | "SHA3256" => 32,
        "SHA384" | "SHA3384" => 48,
        "SHA512" | "SHA3512" => 64,
        _ => 32,
    };
    Ok(Some(Value::Int(len)))
}

// SecureRandom — uses OS cryptographic entropy (BCryptGenRandom / /dev/urandom)
// for all random generation. The previous splitmix64 PRNG has been removed from
// all SecureRandom paths to prevent predictable output.

/// Fill a buffer with OS cryptographic entropy.
/// Mirrors crypto_impl::os_random_bytes but inlined here to avoid
/// feature-gate dependency on legacy-synthetic-crypto.
fn sr_os_random_bytes(buf: &mut [u8]) -> bool {
    #[cfg(target_os = "windows")]
    {
        #[link(name = "advapi32")]
        extern "system" {
            #[link_name = "SystemFunction036"]
            fn RtlGenRandom(buf: *mut u8, len: u32) -> u8;
        }
        for chunk in buf.chunks_mut(u32::MAX as usize) {
            let ok = unsafe { RtlGenRandom(chunk.as_mut_ptr(), chunk.len() as u32) };
            if ok == 0 {
                return false;
            }
        }
        true
    }
    #[cfg(not(target_os = "windows"))]
    {
        use std::io::Read;
        if let Ok(mut f) = std::fs::File::open("/dev/urandom") {
            return f.read_exact(buf).is_ok();
        }
        false
    }
}

/// Get a cryptographically random u64 from OS entropy.
fn sr_os_random_u64() -> u64 {
    let mut buf = [0u8; 8];
    if !sr_os_random_bytes(&mut buf) {
        // Fallback: system_entropy_seed uses RandomState which itself uses OS entropy
        return system_entropy_seed();
    }
    u64::from_le_bytes(buf)
}

/// Gather entropy from multiple system sources and mix them into a seed.
/// Used only as a last-resort fallback when direct OS entropy fails.
fn system_entropy_seed() -> u64 {
    use std::collections::hash_map::RandomState;
    use std::hash::{BuildHasher, Hasher};
    let s = RandomState::new();
    let mut h = s.build_hasher();
    let nanos = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_nanos() as u64;
    h.write_u64(nanos);
    let tid = format!("{:?}", std::thread::current().id());
    h.write(tid.as_bytes());
    let s2 = RandomState::new();
    let h2 = s2.build_hasher();
    h.write_u64(h2.finish());
    h.finish()
}

fn native_secure_random_init(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(None),
    };
    let seed = sr_os_random_u64() as i64;
    ctx.set_field(this, 0, Value::Long(seed));
    ctx.set_field(this, 1, Value::Int(0));
    Ok(None)
}

fn sr_next_seed(ctx: &mut dyn NativeContext, this: ObjectRef) -> i64 {
    // Use OS entropy directly for each call (CSPRNG).
    // The object's seed field is updated for compatibility but the output
    // comes from the OS, not from a deterministic PRNG.
    let val = sr_os_random_u64();
    ctx.set_field(this, 0, Value::Long(val as i64));
    val as i64
}

fn native_sr_next_int(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Int(0))),
    };
    let seed = sr_next_seed(ctx, this);
    Ok(Some(Value::Int((seed >> 16) as i32)))
}

fn native_sr_next_int_bound(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Int(0))),
    };
    let bound = match args.get(1) {
        Some(Value::Int(v)) => *v,
        _ => 1,
    };
    if bound <= 0 {
        return Ok(Some(Value::Int(0)));
    }
    let seed = sr_next_seed(ctx, this);
    Ok(Some(Value::Int(
        ((seed >> 16) as i32).unsigned_abs() as i32 % bound,
    )))
}

fn native_sr_next_long(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Long(0))),
    };
    let seed = sr_next_seed(ctx, this);
    Ok(Some(Value::Long(seed)))
}

fn native_sr_next_bytes(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let _this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(None),
    };
    let arr = match args.get(1) {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(None),
    };
    let len = ctx.array_length(arr);
    if len == 0 {
        return Ok(None);
    }
    // Fill the buffer in a single bulk call to the OS CSPRNG instead of
    // burning a 64-bit random draw per byte (which discarded 7/8 of each
    // call's entropy). If the CSPRNG is unavailable we fall back to
    // per-byte `sr_os_random_u64` mixing so we never silently produce
    // deterministic bytes.
    let mut buf = vec![0u8; len];
    if !sr_os_random_bytes(&mut buf) {
        for chunk in buf.chunks_mut(8) {
            let v = sr_os_random_u64().to_le_bytes();
            for (dst, src) in chunk.iter_mut().zip(v.iter()) {
                *dst = *src;
            }
        }
    }
    for (i, &b) in buf.iter().enumerate() {
        ctx.set_array_element(arr, i, Value::Int((b as i8) as i32));
    }
    // Zero the intermediate buffer — cheap defence in depth even though
    // the heap copy in `set_array_element` is already the authoritative
    // destination.
    for b in buf.iter_mut() {
        *b = 0;
    }
    Ok(None)
}

fn native_sr_next_double(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Double(0.0))),
    };
    let seed = sr_next_seed(ctx, this);
    let d = ((seed >> 16) as u32 as f64) / (u32::MAX as f64);
    Ok(Some(Value::Double(d)))
}

fn native_sr_next_boolean(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Int(0))),
    };
    let seed = sr_next_seed(ctx, this);
    Ok(Some(Value::Int(if seed & 1 == 0 { 0 } else { 1 })))
}

fn native_sr_generate_seed(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let num_bytes = match args.get(1) {
        Some(Value::Int(v)) => *v as usize,
        _ => 0,
    };
    let arr = ctx.new_array(cratonvm_types::ArrayElementType::Byte, num_bytes);
    // Use OS entropy directly (CSPRNG) for seed generation.
    let mut buf = vec![0u8; num_bytes];
    if !sr_os_random_bytes(&mut buf) {
        // Fallback: use system_entropy_seed per-byte
        for (i, b) in buf.iter_mut().enumerate() {
            *b = (system_entropy_seed() >> (i % 8 * 8)) as u8;
        }
    }
    for (i, &b) in buf.iter().enumerate() {
        ctx.set_array_element(arr, i, Value::Int(b as i8 as i32));
    }
    Ok(Some(Value::Object(Some(arr))))
}

// ===========================================================================
// Phase 34: ReadWriteLock, Atomic extras, LongAdder
// ===========================================================================

fn register_rwlock_natives(registry: &mut NativeMethodRegistry) {
    // Real AQS is the default (and is explicitly enabled by the Spring Boot
    // runner).  Its `ReentrantReadWriteLock` constructor creates real
    // ReadLock/WriteLock views whose `sync` field points at the real nested
    // `Sync`.  The legacy callbacks below instead manufacture a one-field
    // synthetic view with its parent RWL in slot zero.  That happens to work
    // for the callbacks they replace, but not for any unoverridden real-JDK
    // method: `WriteLock.newCondition()` reads that slot as `Sync` and then
    // tries to invoke `Sync.newCondition()` on the outer RWL, yielding the
    // misleading `ReentrantReadWriteLock.newCondition` NoSuchMethodError.
    // Keep the complete RWL family on real bytecode in this mode; the JIT
    // skip list already protects the AQS family.  StampedLock remains an
    // independent native implementation and must stay registered.
    let real_aqs = std::env::var_os("CRATONVM_SYNTHETIC_AQS").is_none()
        || std::env::var_os("CRATONVM_REAL_AQS").is_some();
    if real_aqs {
        register_stamped_lock_natives(registry);
        return;
    }

    let rwl = "java/util/concurrent/locks/ReentrantReadWriteLock";
    let rl = "java/util/concurrent/locks/ReentrantReadWriteLock$ReadLock";
    let wl = "java/util/concurrent/locks/ReentrantReadWriteLock$WriteLock";

    // Do not intercept the real-JDK constructors. Their three reference
    // fields are { readerLock, writerLock, sync }; the historical synthetic
    // initializer wrote integer state into those slots, so a method reference
    // such as ReentrantReadWriteLock::readLock received null. Let genuine
    // bytecode initialize the layout, while keeping the native lock-operation
    // backend below for the returned lock views.
    registry.register(
        rwl,
        "readLock",
        "()Ljava/util/concurrent/locks/ReentrantReadWriteLock$ReadLock;",
        native_rwl_read_lock,
    );
    registry.register(
        rwl,
        "writeLock",
        "()Ljava/util/concurrent/locks/ReentrantReadWriteLock$WriteLock;",
        native_rwl_write_lock,
    );

    // ReadLock = 1-field synthetic (parent=0 → ReentrantReadWriteLock).
    //
    // WP4.7: The lock/unlock/tryLock callbacks now delegate to the
    // process-wide RwLock backend in `crate::stamped_lock` instead of
    // toggling a per-object field. The old field-toggle was effectively
    // unsynchronized (two threads racing on `lock()` would each read
    // readers=0, both bump it to 1, neither would exclude a writer).
    // Real exclusion is now via a Mutex+Condvar slot keyed on the parent
    // RWL's address.
    // Pattern-A fix (bug nb-lib-gckeys §1): key the ReentrantReadWriteLock
    // state table by a GC-stable identity of the parent RWL object (see
    // `gc_stable_lock_key`) rather than its raw heap address. A read/write
    // view obtained before a GC must unlock against the SAME slot afterwards;
    // `parent.as_ptr()` shifts under a moving collector and the lock/unlock
    // pair would diverge, deadlocking the lock or corrupting a neighbour slot.
    fn rwl_parent_addr(ctx: &mut dyn NativeContext, this: ObjectRef) -> Option<usize> {
        match ctx.get_field(this, 0) {
            Value::Object(Some(parent)) => Some(gc_stable_lock_key(ctx, parent)),
            _ => None,
        }
    }

    registry.register(rl, "lock", "()V", |ctx, args| {
        let this = match args.first() {
            Some(Value::Object(Some(o))) => *o,
            _ => return Ok(None),
        };
        if let Some(addr) = rwl_parent_addr(ctx, this) {
            // GC-blocking audit (STW takeover 5-class cluster, 2026-07-13):
            // rw_read_lock's internal contended wait is a raw
            // parking_lot::Condvar::wait with NO GC-blocking-region bracket
            // and no Java-heap touch inside — a thread contending for this
            // lock while a writer holds it stays counted in the STW
            // barrier's `expected` forever (not in JIT, never reaches a
            // safepoint), livelocking any cross-thread STW pause requested
            // while it waits.
            ctx.begin_blocking_region();
            crate::stamped_lock::rw_read_lock(addr, ctx.thread_id());
            ctx.end_blocking_region();
        }
        Ok(None)
    });
    registry.register(rl, "unlock", "()V", |ctx, args| {
        let this = match args.first() {
            Some(Value::Object(Some(o))) => *o,
            _ => return Ok(None),
        };
        if let Some(addr) = rwl_parent_addr(ctx, this) {
            crate::stamped_lock::rw_read_unlock(addr, ctx.thread_id());
        }
        Ok(None)
    });
    registry.register(rl, "tryLock", "()Z", |ctx, args| {
        let this = match args.first() {
            Some(Value::Object(Some(o))) => *o,
            _ => return Ok(Some(Value::Int(0))),
        };
        let ok = match rwl_parent_addr(ctx, this) {
            Some(a) => crate::stamped_lock::rw_try_read_lock(a, ctx.thread_id()),
            None => false,
        };
        Ok(Some(Value::Int(i32::from(ok))))
    });
    registry.register(
        rl,
        "tryLock",
        "(JLjava/util/concurrent/TimeUnit;)Z",
        |ctx, args| {
            // Timed variant — caller already pre-rounded the timeout, and
            // the contention ratio in real apps doesn't justify a pdqueue
            // here. Treat as fast-path tryLock.
            let this = match args.first() {
                Some(Value::Object(Some(o))) => *o,
                _ => return Ok(Some(Value::Int(0))),
            };
            let ok = match rwl_parent_addr(ctx, this) {
                Some(a) => crate::stamped_lock::rw_try_read_lock(a, ctx.thread_id()),
                None => false,
            };
            Ok(Some(Value::Int(i32::from(ok))))
        },
    );
    registry.register(rl, "lockInterruptibly", "()V", |ctx, args| {
        let this = match args.first() {
            Some(Value::Object(Some(o))) => *o,
            _ => return Ok(None),
        };
        if let Some(addr) = rwl_parent_addr(ctx, this) {
            // GC-blocking audit — see the plain `lock()` registration above.
            ctx.begin_blocking_region();
            crate::stamped_lock::rw_read_lock(addr, ctx.thread_id());
            ctx.end_blocking_region();
        }
        Ok(None)
    });

    // WriteLock = 1-field synthetic (parent=0). WP4.7: delegate to the
    // process-wide RwLock backend (see comment on the read lock above).
    registry.register(wl, "lock", "()V", |ctx, args| {
        let this = match args.first() {
            Some(Value::Object(Some(o))) => *o,
            _ => return Ok(None),
        };
        if let Some(addr) = rwl_parent_addr(ctx, this) {
            // GC-blocking audit (STW takeover 5-class cluster, 2026-07-13):
            // rw_write_lock's internal contended wait is a raw
            // parking_lot::Condvar::wait with NO GC-blocking-region bracket
            // and no Java-heap touch inside — see the read-lock `lock()`
            // registration above for the full rationale. Confirmed via
            // symbolicated cdb stacks: TestOrderInterceptor's stuck
            // ForkJoinPool worker threads were parked exactly here, not in
            // LockSupport.park (which IS correctly bracketed) — this was the
            // actual root cause of the STW takeover livelock, not a
            // ForkJoinPool/AQS-specific issue.
            ctx.begin_blocking_region();
            crate::stamped_lock::rw_write_lock(addr, ctx.thread_id());
            ctx.end_blocking_region();
        }
        Ok(None)
    });
    registry.register(wl, "unlock", "()V", |ctx, args| {
        let this = match args.first() {
            Some(Value::Object(Some(o))) => *o,
            _ => return Ok(None),
        };
        if let Some(addr) = rwl_parent_addr(ctx, this) {
            crate::stamped_lock::rw_write_unlock(addr, ctx.thread_id());
        }
        Ok(None)
    });
    registry.register(wl, "tryLock", "()Z", |ctx, args| {
        let this = match args.first() {
            Some(Value::Object(Some(o))) => *o,
            _ => return Ok(Some(Value::Int(0))),
        };
        let ok = match rwl_parent_addr(ctx, this) {
            Some(a) => crate::stamped_lock::rw_try_write_lock(a, ctx.thread_id()),
            None => false,
        };
        Ok(Some(Value::Int(i32::from(ok))))
    });
    registry.register(
        wl,
        "tryLock",
        "(JLjava/util/concurrent/TimeUnit;)Z",
        |ctx, args| {
            let this = match args.first() {
                Some(Value::Object(Some(o))) => *o,
                _ => return Ok(Some(Value::Int(0))),
            };
            let ok = match rwl_parent_addr(ctx, this) {
                Some(a) => crate::stamped_lock::rw_try_write_lock(a, ctx.thread_id()),
                None => false,
            };
            Ok(Some(Value::Int(i32::from(ok))))
        },
    );
    registry.register(wl, "lockInterruptibly", "()V", |ctx, args| {
        let this = match args.first() {
            Some(Value::Object(Some(o))) => *o,
            _ => return Ok(None),
        };
        if let Some(addr) = rwl_parent_addr(ctx, this) {
            // GC-blocking audit — see the plain `lock()` registration above.
            ctx.begin_blocking_region();
            crate::stamped_lock::rw_write_lock(addr, ctx.thread_id());
            ctx.end_blocking_region();
        }
        Ok(None)
    });
    registry.register(wl, "isHeldByCurrentThread", "()Z", |ctx, args| {
        let this = match args.first() {
            Some(Value::Object(Some(o))) => *o,
            _ => return Ok(Some(Value::Int(0))),
        };
        let held = match rwl_parent_addr(ctx, this) {
            Some(a) => crate::stamped_lock::rw_write_is_held(a, ctx.thread_id()),
            None => false,
        };
        Ok(Some(Value::Int(i32::from(held))))
    });

    // StampedLock — real optimistic read / exclusive write lock with stamp validation.
    // Uses a global state map keyed by object address for per-lock state.
    register_stamped_lock_natives(registry);
}

pub fn register_stamped_lock_natives(registry: &mut NativeMethodRegistry) {
    let sl = "java/util/concurrent/locks/StampedLock";
    registry.register(sl, "<init>", "()V", native_stamped_init);
    registry.register(sl, "readLock", "()J", native_stamped_read_lock);
    registry.register(sl, "writeLock", "()J", native_stamped_write_lock);
    registry.register(sl, "tryOptimisticRead", "()J", native_stamped_optimistic);
    registry.register(sl, "unlockRead", "(J)V", native_stamped_unlock_read);
    registry.register(sl, "unlockWrite", "(J)V", native_stamped_unlock_write);
    registry.register(
        sl,
        "unstampedUnlockRead",
        "()V",
        native_stamped_unstamped_unlock_read,
    );
    registry.register(
        sl,
        "unstampedUnlockWrite",
        "()V",
        native_stamped_unstamped_unlock_write,
    );
    registry.register(sl, "tryUnlockRead", "()Z", native_stamped_try_unlock_read);
    registry.register(sl, "tryUnlockWrite", "()Z", native_stamped_try_unlock_write);
    registry.register(sl, "validate", "(J)Z", native_stamped_validate);
    registry.register(sl, "tryReadLock", "()J", native_stamped_try_read_lock);
    registry.register(sl, "tryWriteLock", "()J", native_stamped_try_write_lock);
    registry.register(
        sl,
        "tryConvertToWriteLock",
        "(J)J",
        native_stamped_try_convert_to_write,
    );
    registry.register(
        sl,
        "tryConvertToReadLock",
        "(J)J",
        native_stamped_try_convert_to_read,
    );
    registry.register(sl, "isWriteLocked", "()Z", native_stamped_is_write_locked);
    registry.register(sl, "isReadLocked", "()Z", native_stamped_is_read_locked);
    registry.register(
        sl,
        "getReadLockCount",
        "()I",
        native_stamped_get_read_lock_count,
    );

    let sl_wv = "java/util/concurrent/locks/StampedLock$WriteLockView";
    registry.register(sl_wv, "lock", "()V", native_stamped_write_view_lock);
    registry.register(sl_wv, "tryLock", "()Z", native_stamped_write_view_try_lock);
    registry.register(sl_wv, "unlock", "()V", native_stamped_write_view_unlock);

    let sl_rv = "java/util/concurrent/locks/StampedLock$ReadLockView";
    registry.register(sl_rv, "lock", "()V", native_stamped_read_view_lock);
    registry.register(sl_rv, "tryLock", "()Z", native_stamped_read_view_try_lock);
    registry.register(sl_rv, "unlock", "()V", native_stamped_read_view_unlock);
}

fn native_rwl_init(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(None),
    };
    ctx.set_field(this, 0, Value::Int(0)); // readers
    ctx.set_field(this, 1, Value::Int(0)); // writer
    ctx.set_field(this, 2, Value::Int(0)); // fair
    Ok(None)
}

fn native_rwl_init_fair(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(None),
    };
    let fair = match args.get(1) {
        Some(Value::Int(v)) => *v,
        _ => 0,
    };
    ctx.set_field(this, 0, Value::Int(0));
    ctx.set_field(this, 1, Value::Int(0));
    ctx.set_field(this, 2, Value::Int(fair));
    Ok(None)
}

fn native_rwl_read_lock(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Object(None))),
    };
    let lock = alloc_concurrent_synthetic(
        ctx,
        "java/util/concurrent/locks/ReentrantReadWriteLock$ReadLock",
        1,
    );
    ctx.set_field(lock, 0, Value::Object(Some(this)));
    Ok(Some(Value::Object(Some(lock))))
}

fn native_rwl_write_lock(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Object(None))),
    };
    let lock = alloc_concurrent_synthetic(
        ctx,
        "java/util/concurrent/locks/ReentrantReadWriteLock$WriteLock",
        1,
    );
    ctx.set_field(lock, 0, Value::Object(Some(this)));
    Ok(Some(Value::Object(Some(lock))))
}

// ---------------------------------------------------------------------------
// StampedLock — real implementation backed by `stamped_lock` module.
// ---------------------------------------------------------------------------
//
// WP4.7: The earlier version of this code did `monitor_enter; monitor_wait(5);
// monitor_exit` between observing the state and parking, so a notification
// arriving in that gap was lost — writers blocked for the full 5 ms even
// when contention had already cleared. The fix is to hold a real
// `parking_lot::Mutex` across the check-and-park so `Condvar::wait`
// releases it atomically. All of that lives in `crate::stamped_lock` so
// it can be unit-tested independently of the NativeContext plumbing.
//
// State encoding (see `stamped_lock` module for the full rationale):
//   stamp: i64   — even = no writer, odd = writer active. Starts at 256.
//   readers: i32 — number of active read locks.

const STAMPED_ORIGIN: i64 = crate::stamped_lock::STAMPED_ORIGIN;

// ---------------------------------------------------------------------------
// GC-stable lock-identity key (Pattern-A fix, bug nb-lib-gckeys §1)
//
// The StampedLock / ReentrantReadWriteLock state tables in `stamped_lock`
// are keyed by a `usize` derived from the Java lock object. The previous
// derivation — `o.as_ptr() as usize` — is NOT stable under a moving GC:
// a thread that locks before a young-gen collection computes one key, the
// object is relocated, and the matching `unlock` (after the GC) recomputes
// a DIFFERENT key from the new address → it misses the slot it locked,
// leaving the original slot permanently write-/read-held (deadlock) or
// corrupting an unrelated slot that happens to land at the freed address.
//
// Fix: derive the key from a GC-stable identity. `ctx.identity_hash_code`
// survives relocation (the header hash is preserved/remapped by the
// collector), and a small per-hash generation registry disambiguates the
// rare genuine 32-bit identity-hash collision among live lock objects —
// exactly the scheme `properties_sidetable::key_for` and
// `native-collections`' `widened_obj_key` use. Routing both `stamped_addr`
// and `rwl_parent_addr` through this single helper keeps the lock and
// unlock paths agreeing on a key that no GC can shift.
struct LockKeyEntry {
    last_ptr: usize,
    generation: u32,
}

fn lock_key_registry() -> &'static parking_lot::Mutex<rustc_hash::FxHashMap<u32, Vec<LockKeyEntry>>>
{
    static R: std::sync::OnceLock<
        parking_lot::Mutex<rustc_hash::FxHashMap<u32, Vec<LockKeyEntry>>>,
    > = std::sync::OnceLock::new();
    R.get_or_init(|| parking_lot::Mutex::new(rustc_hash::FxHashMap::default()))
}

#[inline]
fn pack_lock_key(hash: u32, generation: u32) -> usize {
    ((hash as usize) << 32) | (generation as usize)
}

/// Map a Java lock object (or the parent RWL of a read/write view) to a
/// GC-stable `usize` key for the `stamped_lock` state tables. See the
/// module-level note above for the moving-GC deadlock this prevents. The
/// algorithm mirrors `properties_sidetable::key_for`:
///   1. same object seen again at the same address → reuse its generation;
///   2. lone occupant of this hash whose address moved (GC relocation) →
///      rebind to the new address (only when `hash != 0`, i.e. a real
///      assigned identity — hash 0 means "identity not yet assigned" and
///      DISTINCT objects all bucket there, so we must NOT merge them);
///   3. otherwise a new object / genuine collision → fresh generation.
fn gc_stable_lock_key(ctx: &mut dyn NativeContext, obj: ObjectRef) -> usize {
    let hash = ctx.identity_hash_code(obj) as u32;
    let ptr = obj.as_ptr() as usize;
    let mut reg = lock_key_registry().lock();
    let slots = reg.entry(hash).or_default();
    if let Some(slot) = slots.iter().find(|s| s.last_ptr == ptr) {
        return pack_lock_key(hash, slot.generation);
    }
    if hash != 0 && slots.len() == 1 {
        slots[0].last_ptr = ptr;
        return pack_lock_key(hash, slots[0].generation);
    }
    let generation = slots.len() as u32;
    slots.push(LockKeyEntry {
        last_ptr: ptr,
        generation,
    });
    pack_lock_key(hash, generation)
}

// Pattern-A fix (bug nb-lib-gckeys §1): key the StampedLock state table by a
// GC-stable identity (see `gc_stable_lock_key`) instead of the raw, moving
// heap address that the lock/unlock pair could disagree on across a GC.
fn stamped_addr(ctx: &mut dyn NativeContext, args: &[Value]) -> Option<usize> {
    match args.first() {
        Some(Value::Object(Some(o))) => Some(gc_stable_lock_key(ctx, *o)),
        _ => None,
    }
}

fn stamped_obj(args: &[Value]) -> Option<ObjectRef> {
    match args.first() {
        Some(Value::Object(Some(o))) => Some(*o),
        _ => None,
    }
}

fn stamped_addr_for_obj(ctx: &mut dyn NativeContext, obj: ObjectRef) -> usize {
    gc_stable_lock_key(ctx, obj)
}

fn mirror_stamped_state(ctx: &mut dyn NativeContext, obj: ObjectRef, addr: usize) {
    ctx.set_field_by_name(
        obj,
        "state",
        Value::Long(crate::stamped_lock::stamped_visible_state(addr)),
    );
}

fn stamped_view_parent(ctx: &mut dyn NativeContext, args: &[Value]) -> Option<ObjectRef> {
    let view = stamped_obj(args)?;
    match ctx.get_field_by_name(view, "this$0") {
        Value::Object(Some(parent)) => Some(parent),
        _ => None,
    }
}

fn native_stamped_init(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    if let Some(obj) = stamped_obj(args) {
        let addr = stamped_addr_for_obj(ctx, obj);
        crate::stamped_lock::stamped_init(addr);
        mirror_stamped_state(ctx, obj, addr);
    }
    Ok(None)
}

fn native_stamped_write_lock(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let obj = match stamped_obj(args) {
        Some(o) => o,
        None => return Ok(Some(Value::Long(0))),
    };
    let addr = stamped_addr_for_obj(ctx, obj);
    // GC-blocking audit (STW takeover 5-class cluster, 2026-07-13):
    // stamped_write_lock's contended wait is a raw parking_lot::Condvar::wait
    // with NO GC-blocking-region bracket — same missing-bracket bug as
    // ReentrantReadWriteLock's rw_write_lock (see that registration's
    // comment for the full rationale and how this was diagnosed).
    ctx.begin_blocking_region();
    let stamp = crate::stamped_lock::stamped_write_lock(addr);
    ctx.end_blocking_region();
    mirror_stamped_state(ctx, obj, addr);
    Ok(Some(Value::Long(stamp)))
}

fn native_stamped_read_lock(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let obj = match stamped_obj(args) {
        Some(o) => o,
        None => return Ok(Some(Value::Long(0))),
    };
    let addr = stamped_addr_for_obj(ctx, obj);
    // GC-blocking audit — see `native_stamped_write_lock` above.
    ctx.begin_blocking_region();
    let stamp = crate::stamped_lock::stamped_read_lock(addr);
    ctx.end_blocking_region();
    mirror_stamped_state(ctx, obj, addr);
    Ok(Some(Value::Long(stamp)))
}

fn native_stamped_try_read_lock(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let obj = match stamped_obj(args) {
        Some(o) => o,
        None => return Ok(Some(Value::Long(0))),
    };
    let addr = stamped_addr_for_obj(ctx, obj);
    let stamp = crate::stamped_lock::stamped_try_read_lock(addr);
    mirror_stamped_state(ctx, obj, addr);
    Ok(Some(Value::Long(stamp)))
}

fn native_stamped_try_write_lock(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let obj = match stamped_obj(args) {
        Some(o) => o,
        None => return Ok(Some(Value::Long(0))),
    };
    let addr = stamped_addr_for_obj(ctx, obj);
    let stamp = crate::stamped_lock::stamped_try_write_lock(addr);
    mirror_stamped_state(ctx, obj, addr);
    Ok(Some(Value::Long(stamp)))
}

fn native_stamped_write_view_lock(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let Some(parent) = stamped_view_parent(ctx, args) else {
        return Ok(None);
    };
    let addr = stamped_addr_for_obj(ctx, parent);
    // GC-blocking audit — see `native_stamped_write_lock` above.
    ctx.begin_blocking_region();
    crate::stamped_lock::stamped_write_lock(addr);
    ctx.end_blocking_region();
    mirror_stamped_state(ctx, parent, addr);
    Ok(None)
}

fn native_stamped_write_view_try_lock(
    ctx: &mut dyn NativeContext,
    args: &[Value],
) -> MethodCallResult {
    let Some(parent) = stamped_view_parent(ctx, args) else {
        return Ok(Some(Value::Int(0)));
    };
    let addr = stamped_addr_for_obj(ctx, parent);
    let stamp = crate::stamped_lock::stamped_try_write_lock(addr);
    mirror_stamped_state(ctx, parent, addr);
    Ok(Some(Value::Int(i32::from(stamp != 0))))
}

fn native_stamped_write_view_unlock(
    ctx: &mut dyn NativeContext,
    args: &[Value],
) -> MethodCallResult {
    let Some(parent) = stamped_view_parent(ctx, args) else {
        return Ok(None);
    };
    let addr = stamped_addr_for_obj(ctx, parent);
    if !crate::stamped_lock::stamped_try_unstamped_unlock_write(addr) {
        return Err(RuntimeError::IllegalMonitorStateException {
            message: "StampedLock write lock not held".to_string(),
        }
        .into());
    }
    mirror_stamped_state(ctx, parent, addr);
    Ok(None)
}

